// Generated by scripts/build_res4lyf_page.py. Notes are ours, written from reading each node's source; no code from the pack.
export const NODES = [{"n": "AdvancedNoise", "g": "Noise", "d": "Creates a NOISE object holding a seed, noise type, alpha and k, and generates the noise only when a sampler asks for it. Alpha and k are only applied when the type is exactly fractal.", "u": "When a sampler takes a NOISE input and you want one of the pack's noise types.", "src": "nodes_latents.py:29", "s": "ran", "e": "", "t": "", "j": "res4lyf_renders/nodes/AdvancedNoise.json", "w": ""}, {"n": "Base64ToConditioning", "g": "Conditioning tools", "d": "Turns a base64 string from ConditioningToBase64 back into conditioning. It uses a restricted unpickler that only allows listed tensor and collection classes, and refuses anything else to block code execution from crafted workflows.", "u": "To load conditioning that was encoded elsewhere.", "src": "conditioning.py:523", "s": "error", "e": "EOFError: Ran out of input\n", "t": "", "j": "res4lyf_renders/nodes/Base64ToConditioning.json", "w": "CONDITIONING"}, {"n": "BongSampler", "g": "Samplers", "d": "Simplified sampler with a short list of res samplers, where the _sde names set eta to 0.5 and the others set it to 0. It builds the sampler with Bongmath on and runs SharkSampler, returning the latent.", "u": "For a basic res sampler run with few settings.", "src": "beta/samplers.py:2357", "s": "error", "e": "NameError: name 'options' is not defined\n", "t": "", "j": "res4lyf_renders/nodes/BongSampler.json", "w": "LATENT"}, {"n": "CLIPTextEncodeFluxUnguided", "g": "Conditioning tools", "d": "Encodes separate CLIP-L and T5 prompts without adding a guidance value, and also outputs where each prompt's tokens end. A code comment asks whether the T5 search loop has a bug, because it loops over the CLIP-L length.", "u": "When you want Flux text encoding with no guidance value attached.", "src": "conditioning.py:97", "s": "error", "e": "KeyError: 't5xxl'\n", "t": "", "j": "res4lyf_renders/nodes/CLIPTextEncodeFluxUnguided.json", "w": "CONDITIONING"}, {"n": "ClownGuide_AdaIN_MMDiT_Beta", "g": "Style guides", "d": "Stores a reference latent, a strength schedule, a mask and per-block weights for AdaIN, which the sampler passes to the model. In this copy, no file in the model folders reads those AdaIN block settings for HiDream, so the node may have no effect there.", "u": "", "src": "beta/samplers_extensions.py:2750", "s": "error", "e": "KeyError: 'sort_and_scatter'\n", "t": "", "j": "res4lyf_renders/nodes/ClownGuide_AdaIN_MMDiT_Beta.json", "w": "GUIDES"}, {"n": "ClownGuide_AttnInj_MMDiT_Beta", "g": "Style guides", "d": "Stores a reference latent, per-block weights and attention injection strengths (q, k, v), which the sampler passes to the model. No file in the model folders of this copy reads these attention injection settings, so it looks unused.", "u": "", "src": "beta/samplers_extensions.py:2886", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownGuide_AttnInj_MMDiT_Beta.jpg", "j": "res4lyf_renders/nodes/ClownGuide_AttnInj_MMDiT_Beta.json", "w": "GUIDES"}, {"n": "ClownGuide_Beta", "g": "Image guides", "d": "Single-guide front end to ClownGuides: takes one guide latent, mode, strength schedule, step range and mask, inverts the mask, and returns a guides bundle.", "u": "When one reference latent should steer sampling.", "src": "beta/samplers_extensions.py:2151", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownGuide_Beta.jpg", "j": "res4lyf_renders/nodes/ClownGuide_Beta.json", "w": "GUIDES"}, {"n": "ClownGuide_FrequencySeparation", "g": "Style guides", "d": "Adds low-pass method, sigma, kernel sizes, stride and low and high frequency weights to the guides, for style methods that treat image detail and broad tone separately. The model code then blends low frequencies from the guide with high frequencies from the output.", "u": "Tooltips say low sigma stays closer to the guide and the weights can sharpen or blur.", "src": "beta/samplers_extensions.py:1135", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownGuide_FrequencySeparation.jpg", "j": "res4lyf_renders/nodes/ClownGuide_FrequencySeparation.json", "w": "GUIDES"}, {"n": "ClownGuide_Mean_Beta", "g": "Image guides", "d": "Adds a guide that matches only the average value of the reference. During each substep the sampler shifts the prediction's overall mean toward the guide's, with strength set by the weight schedule and mask.", "u": "", "src": "beta/samplers_extensions.py:1057", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownGuide_Mean_Beta.jpg", "j": "res4lyf_renders/nodes/ClownGuide_Mean_Beta.json", "w": "GUIDES"}, {"n": "ClownGuide_SelfRefine", "g": "Image guides", "d": "Sets up a self-refine guide with no reference image. The sampler compares its current result with an earlier one, builds a certainty mask from a threshold, and guides only the stable areas, or the changing areas when inverted.", "u": "", "src": "beta/samplers_extensions.py:2403", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownGuide_SelfRefine.jpg", "j": "res4lyf_renders/nodes/ClownGuide_SelfRefine.json", "w": "GUIDES"}, {"n": "ClownGuide_Style_Beta", "g": "Style guides", "d": "Adds a reference latent, method (such as WCT), strength schedule and mask to the guides, aimed at positive, negative, denoised or all. The model code then pulls its internal features toward the reference's statistics.", "u": "When you want the lighting, colour or style of a reference image; the node description suggests chaining two copies if CFG causes burn.", "src": "beta/samplers_extensions.py:1196", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownGuide_Style_Beta.jpg", "j": "res4lyf_renders/nodes/ClownGuide_Style_Beta.json", "w": "GUIDES"}, {"n": "ClownGuide_Style_EdgeWidth", "g": "Style guides", "d": "Makes an edge mask of the chosen width from the style guide's existing positive and negative masks and adds it to the guides.", "u": "The description says it can help reduce seams with style types such as scattersort.", "src": "beta/samplers_extensions.py:1315", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownGuide_Style_EdgeWidth.jpg", "j": "res4lyf_renders/nodes/ClownGuide_Style_EdgeWidth.json", "w": "GUIDES"}, {"n": "ClownGuide_Style_TileSize", "g": "Style guides", "d": "Stores a tile height, width and padding for the style guide, each divided by 16.", "u": "The description says it can improve adherence to the input image with style types such as scattersort.", "src": "beta/samplers_extensions.py:1353", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownGuide_Style_TileSize.jpg", "j": "res4lyf_renders/nodes/ClownGuide_Style_TileSize.json", "w": "GUIDES"}, {"n": "ClownGuide_StyleNorm_Advanced_HiDream", "g": "Style guides", "d": "Stores a reference latent, block weights, a mode and a long list of on/off switches for HiDream layers, which the sampler passes to the model. No file in the model folders of this copy reads the resulting sort_and_scatter settings, so it looks unused.", "u": "", "src": "beta/samplers_extensions.py:3073", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownGuide_StyleNorm_Advanced_HiDream.jpg", "j": "res4lyf_renders/nodes/ClownGuide_StyleNorm_Advanced_HiDream.json", "w": "GUIDES"}, {"n": "ClownGuides_Beta", "g": "Image guides", "d": "Packs two guide latents, one for the masked area and one for the unmasked area, with separate strengths, schedules and step ranges. The chosen mode gets _projection or _cw added to its name when those switches are on.", "u": "When different regions should follow different reference latents.", "src": "beta/samplers_extensions.py:2251", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownGuides_Beta.jpg", "j": "res4lyf_renders/nodes/ClownGuides_Beta.json", "w": "GUIDES"}, {"n": "ClownGuides_Sync", "g": "Image guides", "d": "Sets up sync guide mode with masked and unmasked guide latents, each with a guide weight schedule and a separate sync weight schedule. In sync mode the sampler also runs the model on a noised copy of the guide and combines the two results.", "u": "", "src": "beta/samplers_extensions.py:1397", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownGuides_Sync.jpg", "j": "res4lyf_renders/nodes/ClownGuides_Sync.json", "w": "GUIDES"}, {"n": "ClownGuides_Sync_Advanced", "g": "Image guides", "d": "Sync guide setup with extra schedules and masks. Drift moves the guide target toward model predictions, and lure re-runs the model on latents shifted toward the other path's prediction.", "u": "", "src": "beta/samplers_extensions.py:1613", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownGuides_Sync_Advanced.jpg", "j": "res4lyf_renders/nodes/ClownGuides_Sync_Advanced.json", "w": "GUIDES"}, {"n": "ClownGuides_VideoAudioMask", "g": "Image guides", "d": "Builds a mask for packed video and audio latents that selects a start-to-end time range, using each model preset's frame and audio rates. An optional spatial mask can limit the video part, and the result is flattened for packed latents.", "u": "When a guide should affect only part of a clip's time range, or only its video or audio.", "src": "beta/samplers_extensions.py:4770", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownGuides_VideoAudioMask.jpg", "j": "res4lyf_renders/nodes/ClownGuides_VideoAudioMask.json", "w": "MASK"}, {"n": "ClownGuidesAB_Beta", "g": "Image guides", "d": "Same output as ClownGuides but with A and B naming and a mask for each guide. If only B is given it becomes A, and a missing mask A is made by inverting mask B.", "u": "", "src": "beta/samplers_extensions.py:2484", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownGuidesAB_Beta.jpg", "j": "res4lyf_renders/nodes/ClownGuidesAB_Beta.json", "w": "GUIDES"}, {"n": "ClownInpaint", "g": "Legacy samplers and options", "d": "Deprecated. Sets up inpainting by using the latent as both guides, building regional conditioning from inpaint and background prompts with the mask, patching the model with ReFlux, and outputting an empty latent. The guide mode is fixed to epsilon because its widget is commented out.", "u": "For older Flux-oriented inpainting workflows.", "src": "legacy/samplers_extensions.py:115", "s": "error", "e": "TypeError: unsupported operand type(s) for -: 'int' and 'NoneType'\n", "t": "", "j": "res4lyf_renders/nodes/ClownInpaint.json", "w": "GUIDES"}, {"n": "ClownInpaintSimple", "g": "Legacy samplers and options", "d": "Deprecated. A reduced ClownInpaint with only an inpaint prompt and one guide weight. The background prompt falls back to zeros, and its self-attention floor is 1.0 where ClownInpaint uses 0.0.", "u": "For older Flux-oriented inpainting workflows with fewer settings.", "src": "legacy/samplers_extensions.py:193", "s": "error", "e": "TypeError: unsupported operand type(s) for -: 'int' and 'NoneType'\n", "t": "", "j": "res4lyf_renders/nodes/ClownInpaintSimple.json", "w": "GUIDES"}, {"n": "ClownModelLoader", "g": "Loaders", "d": "A general loader for a model, up to four text encoders and a VAE, where text encoders and VAE can each be left out. The encoder type can be picked by hand or set to .auto, which guesses it from the model's class.", "u": "Use it for model families that have no dedicated loader in the pack.", "src": "loaders.py:324", "s": "skipped", "e": "loads a whole model chosen by its own settings", "t": "", "j": "", "w": ""}, {"n": "ClownOptions_Automation_Beta", "g": "General options", "d": "Bundles optional per-step lists for eta, substep eta, s_noise, substep s_noise and epsilon scale, plus custom frame weights, so each step can use its own value.", "u": "When a value should change step by step from a sigmas-type input.", "src": "beta/samplers_extensions.py:751", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownOptions_Automation_Beta.jpg", "j": "res4lyf_renders/nodes/ClownOptions_Automation_Beta.json", "w": "OPTIONS"}, {"n": "ClownOptions_Combine", "g": "General options", "d": "Merges a group of connected option inputs into one options output.", "u": "To tidy several option nodes into one connection.", "src": "beta/samplers_extensions.py:2630", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownOptions_Combine.jpg", "j": "res4lyf_renders/nodes/ClownOptions_Combine.json", "w": "OPTIONS"}, {"n": "ClownOptions_Cycles_Beta", "g": "Noise and step options", "d": "Makes the sampler repeat a run back and forth, with two passes per cycle alternating unsample and resample. It can set separate eta, CFG, sampler and step count for the unsample passes, decay eta after each cycle, and switch Bongmath on or off for unsampling.", "u": "The eta_decay_scale tooltip says decaying eta may help drive convergence.", "src": "beta/samplers_extensions.py:524", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownOptions_Cycles_Beta.jpg", "j": "res4lyf_renders/nodes/ClownOptions_Cycles_Beta.json", "w": "OPTIONS"}, {"n": "ClownOptions_DetailBoost_Beta", "g": "Noise and step options", "d": "Builds per-step weight and eta lists, zero outside the start and end steps, that make the sampler or model work from a shifted noise level. Tooltips say positive weights give a sharper, grittier, more detailed image.", "u": "When you want more or less fine detail over a chosen range of steps.", "src": "beta/samplers_extensions.py:225", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownOptions_DetailBoost_Beta.jpg", "j": "res4lyf_renders/nodes/ClownOptions_DetailBoost_Beta.json", "w": "OPTIONS"}, {"n": "ClownOptions_ExtraOptions_Beta", "g": "General options", "d": "Adds free-form text to the sampler's extra options, which code throughout the pack looks up by name. Chaining appends the text on new lines.", "u": "When setting one of the pack's named switches that has no widget.", "src": "beta/samplers_extensions.py:675", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownOptions_ExtraOptions_Beta.jpg", "j": "res4lyf_renders/nodes/ClownOptions_ExtraOptions_Beta.json", "w": "OPTIONS"}, {"n": "ClownOptions_FlowGuide", "g": "Image guides", "d": "Sets the amount by which flow guide mode blends its step direction with the direction toward the current prediction. It does nothing outside flow mode.", "u": "", "src": "beta/samplers_extensions.py:422", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownOptions_FlowGuide.jpg", "j": "res4lyf_renders/nodes/ClownOptions_FlowGuide.json", "w": "OPTIONS"}, {"n": "ClownOptions_Frameweights", "g": "Image guides", "d": "Adds a per-frame guide weight curve to a shared manager, built from a dynamics type, schedule and scale, or taken from a custom list or string. The guide code reads these weights by name for video frames.", "u": "When a guide should fade across video frames.", "src": "beta/samplers_extensions.py:2657", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownOptions_Frameweights.jpg", "j": "res4lyf_renders/nodes/ClownOptions_Frameweights.json", "w": "OPTIONS"}, {"n": "ClownOptions_FrameWeights", "g": "Legacy samplers and options", "d": "Deprecated. Puts a per-frame weight list into options, used for both the main and background guide masks when the latent is video.", "u": "To vary guide strength by frame in older video workflows.", "src": "legacy/samplers_extensions.py:562", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownOptions_FrameWeights.jpg", "j": "res4lyf_renders/nodes/ClownOptions_FrameWeights.json", "w": "OPTIONS"}, {"n": "ClownOptions_ImplicitSteps_Beta", "g": "Noise and step options", "d": "Sets how many extra refinement passes implicit sampling runs per step and substep, and how each pass picks its starting point (rebound, retro-eta, bongmath or predictor-corrector). The README warns that more implicit steps multiply the runtime.", "u": "When using implicit refinement; the README says gains usually fade after 2-3 implicit steps.", "src": "beta/samplers_extensions.py:484", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownOptions_ImplicitSteps_Beta.jpg", "j": "res4lyf_renders/nodes/ClownOptions_ImplicitSteps_Beta.json", "w": "OPTIONS"}, {"n": "ClownOptions_LatentNormalize", "g": "Noise and step options", "d": "Sets scale factors for the first and second tensors of a packed latent. One value is applied once before sampling, and comma-separated lists are applied per step.", "u": "With packed multi-part latents such as video plus audio.", "src": "beta/samplers_extensions.py:164", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownOptions_LatentNormalize.jpg", "j": "res4lyf_renders/nodes/ClownOptions_LatentNormalize.json", "w": "OPTIONS"}, {"n": "ClownOptions_Momentum_Beta", "g": "Noise and step options", "d": "Sets a momentum value that pushes each prediction further away from the previous one, then recalculates the step direction from it.", "u": "The tooltip says positive values speed convergence when sampling and negative values when unsampling.", "src": "beta/samplers_extensions.py:453", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownOptions_Momentum_Beta.jpg", "j": "res4lyf_renders/nodes/ClownOptions_Momentum_Beta.json", "w": "OPTIONS"}, {"n": "ClownOptions_SDE_Beta", "g": "Noise and step options", "d": "Sets the noise type, noise scaling mode, eta and seed used for the noise added during sampling, with separate values for steps and substeps. Optional per-step eta inputs are passed along, and choosing 'none' for a type or mode sets that eta to 0.", "u": "When steps and substeps need different noise settings.", "src": "beta/samplers_extensions.py:52", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownOptions_SDE_Beta.jpg", "j": "res4lyf_renders/nodes/ClownOptions_SDE_Beta.json", "w": "OPTIONS"}, {"n": "ClownOptions_SDE_Mask_Beta", "g": "Noise and step options", "d": "Rescales a mask to a chosen minimum and maximum and stores it, so added noise can vary by region. The mask is passed to the substep noise swap, and the sampler pads the schedule when it is present.", "u": "When noise should differ between regions.", "src": "beta/samplers_extensions.py:1015", "s": "error", "e": "AttributeError: 'NoneType' object has no attribute 'min'\n", "t": "", "j": "res4lyf_renders/nodes/ClownOptions_SDE_Mask_Beta.json", "w": "OPTIONS"}, {"n": "ClownOptions_SDE_Noise", "g": "Legacy samplers and options", "d": "Deprecated. Puts saved SDE noise and a step count into an options value, which the older sampler reads per step. The noise input is marked optional, but the function requires it.", "u": "To reuse saved SDE noise in older workflows.", "src": "legacy/samplers_extensions.py:531", "s": "error", "e": "AttributeError: 'dict' object has no attribute 'sub_'\n", "t": "", "j": "res4lyf_renders/nodes/ClownOptions_SDE_Noise.json", "w": "OPTIONS"}, {"n": "ClownOptions_SigmaScaling_Beta", "g": "Noise and step options", "d": "Sets extra noise multipliers, a noise anchor, and factors that scale the sigma schedule down or up from chosen steps. Tooltips say lowering the schedule adds detail and raising it softens the image and deepens colours.", "u": "Tooltips suggest s_noise around 1.03-1.07 and lying around 0.98-0.95 for more detail.", "src": "beta/samplers_extensions.py:356", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownOptions_SigmaScaling_Beta.jpg", "j": "res4lyf_renders/nodes/ClownOptions_SigmaScaling_Beta.json", "w": "OPTIONS"}, {"n": "ClownOptions_StepSize_Beta", "g": "Noise and step options", "d": "Sets overshoot amounts and scaling modes for steps and substeps. Tooltips describe it as making each denoising step larger and then rescaling to match the original.", "u": "The tooltips say it has a softening effect.", "src": "beta/samplers_extensions.py:124", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownOptions_StepSize_Beta.jpg", "j": "res4lyf_renders/nodes/ClownOptions_StepSize_Beta.json", "w": "OPTIONS"}, {"n": "ClownOptions_SwapSampler_Beta", "g": "Noise and step options", "d": "Adds a rule that switches to another sampler at a chosen step, or earlier when the difference between res_2m and res_3m estimates falls below a threshold. Several rules can be chained.", "u": "When one sampler should take over part way through a run.", "src": "beta/samplers_extensions.py:966", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownOptions_SwapSampler_Beta.jpg", "j": "res4lyf_renders/nodes/ClownOptions_SwapSampler_Beta.json", "w": "OPTIONS"}, {"n": "ClownOptions_Tile_Advanced_Beta", "g": "General options", "d": "Sets the same tile size list from text with one or more sizes, replacing any list already in the options.", "u": "", "src": "beta/samplers_extensions.py:642", "s": "error", "e": "RuntimeError: shape '[1, 1, 1, 4, 128, 128]' is invalid for input of size 16384\n", "t": "", "j": "res4lyf_renders/nodes/ClownOptions_Tile_Advanced_Beta.json", "w": "OPTIONS"}, {"n": "ClownOptions_Tile_Beta", "g": "General options", "d": "Adds one tile size to a list. The sampler then runs the model tile by tile and stitches the results, moving to the next listed size on each tiled call.", "u": "", "src": "beta/samplers_extensions.py:607", "s": "error", "e": "RuntimeError: shape '[1, 1, 1, 4, 128, 128]' is invalid for input of size 16384\n", "t": "", "j": "res4lyf_renders/nodes/ClownOptions_Tile_Beta.json", "w": "OPTIONS"}, {"n": "ClownpileModelWanVideo", "g": "Compile for speed", "d": "Compiles a WAN model's transformer blocks one by one, leaving out the blocks in skip_self_attn_blocks; force_recompile clears the once-only guard. The tooltip says blocks chosen for regional WAN should be listed there, because compiling them with their large masks takes too much VRAM, and the class is marked experimental.", "u": "Use it to compile WAN while regional self-attention masks are on for some blocks.", "src": "models.py:1564", "s": "error", "e": "RuntimeError: Failed to compile model. Verify that this is a WAN model!\n", "t": "", "j": "res4lyf_renders/nodes/ClownpileModelWanVideo.json", "w": "MODEL"}, {"n": "ClownRegionalConditioning", "g": "Regional prompting", "d": "Adds one prompt and mask to a growing region list that can be chained from node to node. With no mask, it uses whatever area earlier regions left uncovered, and the spineless switch turns off that region's self-attention masking.", "u": "When you need more regions than the fixed two or three input nodes offer.", "src": "conditioning.py:1684", "s": "error", "e": "IndexError: list index out of range\n", "t": "", "j": "res4lyf_renders/nodes/ClownRegionalConditioning.json", "w": ""}, {"n": "ClownRegionalConditioning2", "g": "Regional prompting", "d": "Regional prompting with one mask: one prompt for the masked area and another for everything else, using the inverted mask. It is a thin wrapper around ClownRegionalConditioning_AB.", "u": "When an image splits into a subject area and the rest.", "src": "conditioning.py:1607", "s": "error", "e": "TypeError: ClownRegionalConditioning2.main() missing 1 required positional argument: 'mask'\n", "t": "", "j": "res4lyf_renders/nodes/ClownRegionalConditioning2.json", "w": "CONDITIONING"}, {"n": "ClownRegionalConditioning3", "g": "Regional prompting", "d": "Regional prompting with two masks and a third prompt for the leftover area, computed as one minus both masks and floored at zero. It is a thin wrapper around ClownRegionalConditioning_ABC.", "u": "When two masked areas plus a background each need a prompt.", "src": "conditioning.py:1642", "s": "error", "e": "TypeError: ClownRegionalConditioning3.main() missing 2 required positional arguments: 'mask_A' and 'mask_B'\n", "t": "", "j": "res4lyf_renders/nodes/ClownRegionalConditioning3.json", "w": "CONDITIONING"}, {"n": "ClownRegionalConditioning_AB", "g": "Regional prompting", "d": "Regional prompting with two prompts and two explicit masks, set up through a callback that runs when the sampler supplies the model. Missing prompts are replaced with empty conditioning, pooled outputs are averaged, and mask_type chooses gradient or boolean masks and which region's pixels may attend to the whole image.", "u": "When two regions need their own hand-made masks.", "src": "conditioning.py:1158", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownRegionalConditioning_AB.jpg", "j": "res4lyf_renders/nodes/ClownRegionalConditioning_AB.json", "w": "CONDITIONING"}, {"n": "ClownRegionalConditioning_ABC", "g": "Regional prompting", "d": "The three-prompt, three-mask version of the AB node, working the same way through a sampler-time callback. Pooled outputs from the three prompts are averaged.", "u": "When three regions need their own hand-made masks.", "src": "conditioning.py:1377", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownRegionalConditioning_ABC.jpg", "j": "res4lyf_renders/nodes/ClownRegionalConditioning_ABC.json", "w": "CONDITIONING"}, {"n": "ClownRegionalConditionings", "g": "Regional prompting", "d": "Takes the chained region list and returns a blank conditioning holding a callback, which builds the attention masks once the sampler supplies the model. Weight and region bleed can change per step, and the mask class is picked by model type (WAN, HiDream, SDXL/SD1.5, or a default).", "u": "To finish a chain of ClownRegionalConditioning nodes before the sampler; the README says over 10 zones have been used in one image.", "src": "conditioning.py:1740", "s": "error", "e": "TypeError: 'NoneType' object is not iterable\n", "t": "", "j": "res4lyf_renders/nodes/ClownRegionalConditionings.json", "w": "CONDITIONING"}, {"n": "ClownSampler", "g": "Legacy samplers and options", "d": "Deprecated, shown as Legacy2_ClownSampler. Calls ClownSamplerAdvanced with the substep noise settings copied from the main ones.", "u": "For workflows built on the second-generation samplers.", "src": "legacy/samplers.py:162", "s": "error", "e": "TypeError: sample_rk() got an unexpected keyword argument 'outer_sigmas_len'\n", "t": "", "j": "res4lyf_renders/nodes/ClownSampler.json", "w": "SAMPLER"}, {"n": "ClownSampler_Beta", "g": "Samplers", "d": "Builds the pack's sampler from eta, sampler name, seed, Bongmath, guides and options, and outputs it as a SAMPLER without running it.", "u": "To feed SharkSampler or another node with a SAMPLER input.", "src": "beta/samplers.py:2071", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownSampler_Beta.jpg", "j": "res4lyf_renders/nodes/ClownSampler_Beta.json", "w": "SAMPLER"}, {"n": "ClownSamplerAdvanced", "g": "Legacy samplers and options", "d": "Deprecated, shown as Legacy2_ClownSamplerAdvanced. Builds a sampler object for the rk sampler, with separate main and substep noise settings and implicit steps, merging values from options, automation and guides inputs.", "u": "For workflows built on the second-generation samplers.", "src": "legacy/samplers.py:47", "s": "error", "e": "TypeError: sample_rk() got an unexpected keyword argument 'outer_sigmas_len'\n", "t": "", "j": "res4lyf_renders/nodes/ClownSamplerAdvanced.json", "w": "SAMPLER"}, {"n": "ClownSamplerAdvanced_Beta", "g": "Samplers", "d": "The underlying sampler builder, with widgets for noise, overshoot, detail boost and implicit settings, marked experimental in its schema. It outputs a SAMPLER and is what the other Clown sampler nodes call.", "u": "When you want these settings as widgets rather than option nodes.", "src": "beta/samplers.py:1199", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownSamplerAdvanced_Beta.jpg", "j": "res4lyf_renders/nodes/ClownSamplerAdvanced_Beta.json", "w": "SAMPLER"}, {"n": "ClownSamplerSelector_Beta", "g": "Samplers", "d": "Lets you pick a sampler from the pack's categorized list and outputs its name as a value, without the category prefix.", "u": "To drive several nodes' sampler choice from one place.", "src": "beta/samplers_extensions.py:23", "s": "ran", "e": "", "t": "", "j": "res4lyf_renders/nodes/ClownSamplerSelector_Beta.json", "w": ""}, {"n": "ClownScheduler", "g": "Schedule makers", "d": "Makes a list of values over steps: one pad value before scheduler_start_step, a named scheduler's shape stretched between start_value and end_value (or a straight line for constant), then another pad value to total_steps. As written it needs a model connected, despite the input being optional, because with no model the values are never set; its callback path is unfinished, and it creates tensors on the cuda device.", "u": "To set a value that changes over only part of a run.", "src": "sigmas.py:1269", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownScheduler.jpg", "j": "res4lyf_renders/nodes/ClownScheduler.json", "w": "SIGMAS"}, {"n": "ClownsharkChainsampler_Beta", "g": "Samplers", "d": "Continues from an earlier sampler's output by running ClownsharKSampler with the schedule and step count stored in the latent, using seed -1. You can change sampler type, eta, CFG, guides and options for this stage.", "u": "To change sampler or settings part way through a generation; the README's workflow demonstrates chainsamplers.", "src": "beta/samplers.py:1988", "s": "error", "e": "KeyError: 'state_info'\n", "t": "", "j": "res4lyf_renders/nodes/ClownsharkChainsampler_Beta.json", "w": "OPTIONS"}, {"n": "ClownsharKSampler", "g": "Legacy samplers and options", "d": "Deprecated, shown as Legacy2_ClownsharKSampler. Builds the sampler through ClownSamplerAdvanced and runs it through the older SharkSamplerAlpha, returning output, denoised and SDE noise.", "u": "For workflows built on the second-generation samplers.", "src": "legacy/samplers.py:596", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownsharKSampler.jpg", "j": "res4lyf_renders/nodes/ClownsharKSampler.json", "w": "LATENT"}, {"n": "ClownsharKSampler_Beta", "g": "Samplers", "d": "All-in-one sampler: builds the pack's custom sampler from its settings, guides and options, then runs it through SharkSampler. It covers explicit, multistep, hybrid and implicit samplers, optional noise (eta), Bongmath and sampler modes.", "u": "The README calls it the all-in-one node; only model and latent_image are mandatory.", "src": "beta/samplers.py:1554", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownsharKSampler_Beta.jpg", "j": "res4lyf_renders/nodes/ClownsharKSampler_Beta.json", "w": "OPTIONS"}, {"n": "ClownsharKSamplerAutomation", "g": "Legacy samplers and options", "d": "Deprecated. Packs per-step eta, s_noise and unsample/resample schedules into a plain tuple. The legacy2 sampler reads automation by dictionary key, so these values do not appear to be read from a tuple.", "u": "", "src": "legacy/samplers_extensions.py:392", "s": "ran", "e": "", "t": "", "j": "res4lyf_renders/nodes/ClownsharKSamplerAutomation.json", "w": ""}, {"n": "ClownsharKSamplerAutomation_Advanced", "g": "Legacy samplers and options", "d": "Deprecated. Puts per-step eta, substep eta, s_noise, unsample/resample scale and frame-weight schedules into a dictionary. The legacy2 sampler reads most of these; the substep eta key was not read in the code checked.", "u": "To change noise settings step by step in older workflows.", "src": "legacy/samplers_extensions.py:420", "s": "ran", "e": "", "t": "", "j": "res4lyf_renders/nodes/ClownsharKSamplerAutomation_Advanced.json", "w": ""}, {"n": "ClownsharKSamplerGuide", "g": "Legacy samplers and options", "d": "Deprecated. Packages a single guide latent with its mask, weights, schedule and end step, leaving background values empty or at zero.", "u": "To guide sampling with one latent in older workflows.", "src": "legacy/samplers_extensions.py:268", "s": "error", "e": "AttributeError: 'tuple' object has no attribute 'get'\n", "t": "", "j": "res4lyf_renders/nodes/ClownsharKSamplerGuide.json", "w": "GUIDES"}, {"n": "ClownsharKSamplerGuides", "g": "Legacy samplers and options", "d": "Deprecated. Packages a main guide and a background guide, with their masks, weights, schedules and end steps. Modes that need two latents fall back to epsilon if there is no background guide.", "u": "To guide the masked area and background differently in older workflows.", "src": "legacy/samplers_extensions.py:329", "s": "error", "e": "AttributeError: 'tuple' object has no attribute 'get'\n", "t": "", "j": "res4lyf_renders/nodes/ClownsharKSamplerGuides.json", "w": "GUIDES"}, {"n": "ClownsharKSamplerOptions", "g": "Legacy samplers and options", "d": "Deprecated. Collects noise settings, eta, s_noise, d_noise, RK c1/c2/c3 values and t/sigma formulas into an options value that the older samplers read.", "u": "To set less common sampler settings in older workflows.", "src": "legacy/samplers_extensions.py:461", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownsharKSamplerOptions.jpg", "j": "res4lyf_renders/nodes/ClownsharKSamplerOptions.json", "w": "OPTIONS"}, {"n": "ClownStyle_Attn_MMDiT", "g": "Style layer controls", "d": "Sets style transfer strengths inside the attention layers of chosen MMDiT blocks (q, k, v projections, q and k norms, and output), for image and text streams.", "u": "When style should act on attention layers specifically.", "src": "beta/samplers_extensions.py:3734", "s": "ran", "e": "", "t": "", "j": "res4lyf_renders/nodes/ClownStyle_Attn_MMDiT.json", "w": ""}, {"n": "ClownStyle_Attn_UNet", "g": "Style layer controls", "d": "Sets style transfer strengths inside the self-attention or cross-attention layers (q, k, v, output) of chosen UNet blocks.", "u": "", "src": "beta/samplers_extensions.py:4135", "s": "ran", "e": "", "t": "", "j": "res4lyf_renders/nodes/ClownStyle_Attn_UNet.json", "w": ""}, {"n": "ClownStyle_Block_MMDiT", "g": "Style layer controls", "d": "Sets style transfer mode and strengths for parts of chosen double or single blocks in MMDiT-type models (attention, feed-forward, norms, residuals), for image and text streams. Block lists and per-block weights can be given, and results collect in a BLOCKS output.", "u": "When style should act on specific transformer blocks.", "src": "beta/samplers_extensions.py:3566", "s": "ran", "e": "", "t": "", "j": "res4lyf_renders/nodes/ClownStyle_Block_MMDiT.json", "w": ""}, {"n": "ClownStyle_Block_UNet", "g": "Style layer controls", "d": "Sets style transfer mode and strengths for the resample, res and spatial parts of chosen input, middle or output UNet blocks.", "u": "", "src": "beta/samplers_extensions.py:4002", "s": "ran", "e": "", "t": "", "j": "res4lyf_renders/nodes/ClownStyle_Block_UNet.json", "w": ""}, {"n": "ClownStyle_Boost", "g": "Style layer controls", "d": "Adds strength settings to the style setup: a noise mode, a recon_lure method, and a data shock that restyles the image or prediction over chosen steps.", "u": "Tooltips say data shock greatly raises strength at low denoise in img2img, and recon_lure can raise style strength in recon noise mode.", "src": "beta/samplers_extensions.py:3398", "s": "error", "e": "AttributeError: 'NoneType' object has no attribute 'embed'\n", "t": "", "j": "res4lyf_renders/nodes/ClownStyle_Boost.json", "w": "GUIDES"}, {"n": "ClownStyle_MMDiT", "g": "Style layer controls", "d": "Creates or extends the MMDiT style setup with a reference latent, mask, mode, input and output projection strengths, tile size and optional conditioning, and adds connected block settings to the guides. Repeated use merges weights.", "u": "As the node that feeds block-level MMDiT style settings into the guides.", "src": "beta/samplers_extensions.py:3472", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownStyle_MMDiT.jpg", "j": "res4lyf_renders/nodes/ClownStyle_MMDiT.json", "w": "GUIDES"}, {"n": "ClownStyle_ResBlock_UNet", "g": "Style layer controls", "d": "Sets style transfer strengths for the individual layers of the residual section in chosen UNet blocks (input, timestep embedding, output and residual).", "u": "", "src": "beta/samplers_extensions.py:4294", "s": "ran", "e": "", "t": "", "j": "res4lyf_renders/nodes/ClownStyle_ResBlock_UNet.json", "w": ""}, {"n": "ClownStyle_SpatialBlock_UNet", "g": "Style layer controls", "d": "Sets style transfer strengths for the spatial transformer section of chosen UNet blocks (input norm and projection, transformer, output projection and residual).", "u": "", "src": "beta/samplers_extensions.py:4460", "s": "ran", "e": "", "t": "", "j": "res4lyf_renders/nodes/ClownStyle_SpatialBlock_UNet.json", "w": ""}, {"n": "ClownStyle_TransformerBlock_UNet", "g": "Style layer controls", "d": "Sets style transfer strengths for the layers inside the transformer block of chosen UNet blocks (norms, self-attention, cross-attention, feed-forward and their residuals).", "u": "", "src": "beta/samplers_extensions.py:4612", "s": "ran", "e": "", "t": "", "j": "res4lyf_renders/nodes/ClownStyle_TransformerBlock_UNet.json", "w": ""}, {"n": "ClownStyle_UNet", "g": "Style layer controls", "d": "The UNet version of ClownStyle_MMDiT: sets up style with a reference latent, mask, mode, projection strengths, tile size and optional conditioning, and adds connected block settings to the guides.", "u": "As the node that feeds block-level UNet style settings into the guides.", "src": "beta/samplers_extensions.py:3897", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ClownStyle_UNet.jpg", "j": "res4lyf_renders/nodes/ClownStyle_UNet.json", "w": "GUIDES"}, {"n": "Conditioning Recast FP64", "g": "Precision", "d": "Converts the main tensor and pooled output of the first entry in one or two conditioning inputs to 64-bit floats, changing them in place. Later entries in a conditioning list are left alone, and the node is flagged experimental.", "u": "When conditioning needs to match a 64-bit sampling workflow.", "src": "conditioning.py:407", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Conditioning_Recast_FP64.jpg", "j": "res4lyf_renders/nodes/Conditioning_Recast_FP64.json", "w": "CONDITIONING"}, {"n": "ConditioningAdd", "g": "Conditioning tools", "d": "Adds a scaled copy of the second conditioning to the first, for both the text embedding and the pooled output. It works on the first entry only and changes the first input in place.", "u": "When you want to add one prompt's embedding on top of another.", "src": "conditioning.py:222", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ConditioningAdd.jpg", "j": "res4lyf_renders/nodes/ConditioningAdd.json", "w": "CONDITIONING"}, {"n": "ConditioningAverageScheduler", "g": "Conditioning tools", "d": "Averages two conditionings at a different ratio for each entry in a schedule, giving each result an equal slice of the sampling timeline. It is marked experimental, and a code comment says the author does not think it is implemented correctly and that it needs reworking.", "u": "", "src": "conditioning.py:317", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ConditioningAverageScheduler.jpg", "j": "res4lyf_renders/nodes/ConditioningAverageScheduler.json", "w": "CONDITIONING"}, {"n": "ConditioningBatch4", "g": "Conditioning tools", "d": "Collects up to four conditionings into a list, keeping each one as its own element rather than merging their entries.", "u": "", "src": "conditioning.py:604", "s": "error", "e": "IndexError: list index out of range\n", "t": "", "j": "res4lyf_renders/nodes/ConditioningBatch4.json", "w": "CONDITIONING"}, {"n": "ConditioningBatch8", "g": "Conditioning tools", "d": "Collects up to eight conditionings into a list, keeping each one as its own element rather than merging their entries.", "u": "", "src": "conditioning.py:640", "s": "error", "e": "IndexError: list index out of range\n", "t": "", "j": "res4lyf_renders/nodes/ConditioningBatch8.json", "w": "CONDITIONING"}, {"n": "ConditioningDownsample (T5)", "g": "Conditioning tools", "d": "Shrinks a text embedding to a token limit by padding it to a square grid, resizing that grid with bicubic interpolation, and flattening it back. It changes only the first entry's embedding and is marked experimental.", "u": "When a long text embedding must be reduced to fewer tokens.", "src": "conditioning.py:544", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ConditioningDownsample_T5_.jpg", "j": "res4lyf_renders/nodes/ConditioningDownsample_T5_.json", "w": "CONDITIONING"}, {"n": "ConditioningOrthoCollin", "g": "Conditioning tools", "d": "Mixes two conditionings by splitting them into parts that point the same way (collinear) and parts at right angles (orthogonal). The text embedding blends the two collinear parts by t5_strength, and the pooled output moves toward a collinear-plus-orthogonal mix by clip_strength. It is marked experimental and changes its first input in place.", "u": "", "src": "conditioning.py:53", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ConditioningOrthoCollin.jpg", "j": "res4lyf_renders/nodes/ConditioningOrthoCollin.json", "w": "CONDITIONING"}, {"n": "ConditioningToBase64", "g": "Conditioning tools", "d": "Pickles a conditioning and encodes it as a base64 string, showing the string on the node and saving it into the workflow's widget values.", "u": "A code comment gives the purpose: API use, offloading T5 processing to another machine to avoid model shuffling.", "src": "conditioning.py:434", "s": "ran", "e": "", "t": "", "j": "res4lyf_renders/nodes/ConditioningToBase64.json", "w": ""}, {"n": "ConditioningTruncate", "g": "Conditioning tools", "d": "Deprecated. Cuts SD3 conditioning to 154 tokens and 2048 pooled values, and raises an error for any other model.", "u": "Its error message says to remove it or use ConditioningZeroAndTruncate for negatives.", "src": "conditioning.py:182", "s": "error", "e": "ValueError: ConditioningTruncate only works with SD3 conditioning and is deprecated. Remove it, or use ConditioningZeroAndTruncate for negatives.\n", "t": "", "j": "res4lyf_renders/nodes/ConditioningTruncate.json", "w": "CONDITIONING"}, {"n": "ConditioningZeroAndTruncate", "g": "Conditioning tools", "d": "Zeroes the text embeddings and keeps every other key. If the model or the conditioning's shape indicates SD3, it also cuts the result to the 154-token empty-prompt length.", "u": "To make an empty negative prompt; a code comment says extra zeroed tokens shift the unconditional prediction on joint-attention models.", "src": "conditioning.py:165", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/ConditioningZeroAndTruncate.jpg", "j": "res4lyf_renders/nodes/ConditioningZeroAndTruncate.json", "w": "CONDITIONING"}, {"n": "Constant Scheduler", "g": "Schedule makers", "d": "Makes a list of steps + 1 values that holds value_start until cutoff_percent of the way through, then holds value_end.", "u": "To switch a value at one point in a run.", "src": "sigmas.py:1237", "s": "error", "e": "IndexError: index 1 is out of bounds for dimension 0 with size 1\n", "t": "", "j": "res4lyf_renders/nodes/Constant_Scheduler.json", "w": "SIGMAS"}, {"n": "CrossAttn_EraseReplace_HiDream", "g": "Conditioning tools", "d": "Encodes HiDream T5 and Llama prompts for an erase text and a replace text, returning replace as positive and erase as negative. The four *_token inputs are tokenized but never used in the output, and the node is marked experimental.", "u": "", "src": "conditioning.py:2023", "s": "error", "e": "KeyError: 't5xxl'\n", "t": "", "j": "res4lyf_renders/nodes/CrossAttn_EraseReplace_HiDream.json", "w": "CONDITIONING"}, {"n": "EmptyLatentImage64", "g": "Create and move", "d": "Creates an all-zero 4-channel latent at one eighth of the given size, stored in 64-bit.", "u": "When you start a 4-channel image workflow at 64-bit precision.", "src": "nodes_latents.py:1971", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/EmptyLatentImage64.jpg", "j": "res4lyf_renders/nodes/EmptyLatentImage64.json", "w": "LATENT"}, {"n": "EmptyLatentImageCustom", "g": "Create and move", "d": "Creates an all-zero latent with 4 or 16 channels and 16, 32 or 64-bit precision. The size is divided by 8 for sdxl, 4 for cascade_b, the compression value for cascade_c, or left exact.", "u": "When you need an empty latent with a specific channel count, precision or compression, including Stable Cascade stages.", "src": "nodes_latents.py:1907", "s": "rejected", "e": "Value not in list: mode: 'default' not in ['sdxl', 'cascade_b', 'cascade_c', 'exact']", "t": "", "j": "res4lyf_renders/nodes/EmptyLatentImageCustom.json", "w": "LATENT"}, {"n": "Film Grain", "g": "Image filters and frequency separation", "d": "Adds grain by scattering random gray values over an upscaled grayscale copy, blurring and shrinking it, enhancing edges, then blending it with the image and adjusting brightness. A code comment describes it as a rewrite of the WAS Film Grain node.", "u": "To add film-style grain with control over density, intensity and brightness.", "src": "images.py:307", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Film_Grain.jpg", "j": "res4lyf_renders/nodes/Film_Grain.json", "w": "IMAGE"}, {"n": "FluxGuidanceDisable", "g": "Flux conditioning tweaks", "d": "Turns off Flux's guidance embedding flag on a copy of the model, and can also blank the CLIP-L pooled vector to zeros on every model call. The two switches work separately.", "u": "Use it to run Flux without its guidance embedding or CLIP-L pooled input.", "src": "models.py:1009", "s": "error", "e": "AttributeError: 'UNetModel' object has no attribute 'params'\n", "t": "", "j": "res4lyf_renders/nodes/FluxGuidanceDisable.json", "w": "MODEL"}, {"n": "FluxLoader", "g": "Loaders", "d": "Loads a Flux model, one or two text encoders, a VAE, and optionally a CLIP Vision and a style model, all from one node. It sets the random seed to 42 before loading, can use the encoder and VAE inside a checkpoint, and offers TAESD preview VAEs when both their files exist.", "u": "Use it to load a full Flux setup, including Redux-style parts, without separate loader nodes.", "src": "loaders.py:224", "s": "skipped", "e": "loads a whole model chosen by its own settings", "t": "", "j": "", "w": ""}, {"n": "FluxOrthoCFGPatcher", "g": "Flux conditioning tweaks", "d": "Before each Flux model call, it repeats 500 times the step of removing from the first batch entry's T5 and CLIP-L conditioning whatever points along the second entry's. It can then zero the first entry's CLIP-L vector; the class is marked experimental.", "u": "", "src": "models.py:961", "s": "error", "e": "TypeError: FluxOrthoCFGPatcher.main.<locals>.patched_forward() missing 2 required positional arguments: 'y' and 'guidance'\n", "t": "", "j": "res4lyf_renders/nodes/FluxOrthoCFGPatcher.json", "w": "MODEL"}, {"n": "Frame Select", "g": "Video frames and temporal masks", "d": "Picks one frame from an image batch by index and returns it as a one-image batch.", "u": "To pull a single frame out of a video or batch.", "src": "images.py:530", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Frame_Select.jpg", "j": "res4lyf_renders/nodes/Frame_Select.json", "w": "IMAGE"}, {"n": "Frame Select Latent", "g": "Video frames", "d": "Picks one frame from a video latent by index and returns it as a one-frame latent with only samples. The input is declared as IMAGE, but the code reads it as a latent.", "u": "When you want one frame from a video latent.", "src": "nodes_latents.py:943", "s": "error", "e": "IndexError: too many indices for tensor of dimension 4\n", "t": "", "j": "res4lyf_renders/nodes/Frame_Select_Latent.json", "w": "LATENT"}, {"n": "Frame Select Latent Raw", "g": "Video frames", "d": "Picks one frame by index from state_info's raw_x rather than from samples. It returns a bare tensor instead of the usual latent dictionary even though the output is labeled LATENT, and its input is declared as IMAGE.", "u": "", "src": "nodes_latents.py:862", "s": "error", "e": "IndexError: too many indices for tensor of dimension 4\n", "t": "", "j": "res4lyf_renders/nodes/Frame_Select_Latent_Raw.json", "w": "LATENT"}, {"n": "Frames Concat", "g": "Video frames and temporal masks", "d": "Joins two image batches into one, first batch first.", "u": "To put two runs of frames end to end.", "src": "images.py:584", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Frames_Concat.jpg", "j": "res4lyf_renders/nodes/Frames_Concat.json", "w": "IMAGE"}, {"n": "Frames Concat Latent", "g": "Video frames", "d": "Joins two video latents along the frame dimension and returns a new latent with only samples.", "u": "When you want to join two video latents end to end.", "src": "nodes_latents.py:997", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Frames_Concat_Latent.jpg", "j": "res4lyf_renders/nodes/Frames_Concat_Latent.json", "w": "LATENT"}, {"n": "Frames Concat Latent Raw", "g": "Video frames", "d": "Joins two inputs along the frame dimension and returns a bare tensor. It concatenates the inputs directly, so it works with the tensors the other Raw frame nodes output and not with an ordinary latent dictionary.", "u": "When you want to join frame ranges taken with the Raw select and slice nodes.", "src": "nodes_latents.py:916", "s": "error", "e": "TypeError: expected Tensor as element 0 in argument 0, but got dict\n", "t": "", "j": "res4lyf_renders/nodes/Frames_Concat_Latent_Raw.json", "w": "LATENT"}, {"n": "Frames Concat Masks", "g": "Video frames and temporal masks", "d": "Joins 2 to 10 masks along the frame dimension and adds a leading dimension if the result has only three.", "u": "To build a mask that changes over time from several pieces.", "src": "nodes_latents.py:1026", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Frames_Concat_Masks.jpg", "j": "res4lyf_renders/nodes/Frames_Concat_Masks.json", "w": "MASK"}, {"n": "Frames Latent ReverseOrder", "g": "Video frames and temporal masks", "d": "Returns a video latent with its frames in reverse order. It expects a 5-dimensional latent and outputs only the samples, dropping other latent keys.", "u": "When a video latent needs to play backward.", "src": "nodes_latents.py:1137", "s": "error", "e": "IndexError: too many indices for tensor of dimension 4\n", "t": "", "j": "res4lyf_renders/nodes/Frames_Latent_ReverseOrder.json", "w": "LATENT"}, {"n": "Frames Masks Uninterpolate", "g": "Video frames and temporal masks", "d": "Reduces a per-frame mask to fewer frames by picking evenly spaced frames, using (frames - 1) / chunk size + 1 as the new count.", "u": "When a mask made per video frame needs to match compressed latent frames.", "src": "nodes_latents.py:1077", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Frames_Masks_Uninterpolate.jpg", "j": "res4lyf_renders/nodes/Frames_Masks_Uninterpolate.json", "w": "MASK"}, {"n": "Frames Masks ZeroOut", "g": "Video frames and temporal masks", "d": "Changes one chosen frame of a time mask in place. Despite the name, the code sets that frame to 1.0, not 0.", "u": "", "src": "nodes_latents.py:1111", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Frames_Masks_ZeroOut.jpg", "j": "res4lyf_renders/nodes/Frames_Masks_ZeroOut.json", "w": "MASK"}, {"n": "Frames Slice", "g": "Video frames and temporal masks", "d": "Returns the images from a start index up to, but not including, a stop index.", "u": "To take a range of frames from a video or batch.", "src": "images.py:557", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Frames_Slice.jpg", "j": "res4lyf_renders/nodes/Frames_Slice.json", "w": "IMAGE"}, {"n": "Frames Slice Latent", "g": "Video frames", "d": "Cuts a range of frames from a video latent, from start up to but not including stop, and returns them as a new latent with only samples.", "u": "When you want a section of a video latent.", "src": "nodes_latents.py:970", "s": "error", "e": "IndexError: too many indices for tensor of dimension 4\n", "t": "", "j": "res4lyf_renders/nodes/Frames_Slice_Latent.json", "w": "LATENT"}, {"n": "Frames Slice Latent Raw", "g": "Video frames", "d": "Cuts a frame range from state_info's raw_x rather than from samples. It returns a bare tensor instead of the usual latent dictionary even though the output is labeled LATENT.", "u": "", "src": "nodes_latents.py:889", "s": "error", "e": "KeyError: 'state_info'\n", "t": "", "j": "res4lyf_renders/nodes/Frames_Slice_Latent_Raw.json", "w": "LATENT"}, {"n": "Frequency Separation Hard Light", "g": "Image filters and frequency separation", "d": "Works both ways: original and low-pass give the high-pass layer, and low-pass and high-pass rebuild the original, using hard light math at 64-bit precision. The code moves this math to CUDA explicitly.", "u": "To edit coarse tones and fine detail separately, then recombine.", "src": "images.py:448", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Frequency_Separation_Hard_Light.jpg", "j": "res4lyf_renders/nodes/Frequency_Separation_Hard_Light.json", "w": "IMAGE"}, {"n": "Frequency Separation Hard Light LAB", "g": "Image filters and frequency separation", "d": "The same hard light split and rebuild, carried out on normalized LAB values and converted back to RGB.", "u": "To do hard light separation in LAB instead of RGB.", "src": "images.py:480", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Frequency_Separation_Hard_Light_LAB.jpg", "j": "res4lyf_renders/nodes/Frequency_Separation_Hard_Light_LAB.json", "w": "IMAGE"}, {"n": "Frequency Separation Linear Light", "g": "Image filters and frequency separation", "d": "Works both ways: original and low-pass give the high-pass detail layer, and low-pass and high-pass rebuild the original, using linear light math at 64-bit precision. The code moves this math to CUDA explicitly.", "u": "To edit coarse tones and fine detail separately, then recombine.", "src": "images.py:677", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Frequency_Separation_Linear_Light.jpg", "j": "res4lyf_renders/nodes/Frequency_Separation_Linear_Light.json", "w": "IMAGE"}, {"n": "Image Channels LAB", "g": "Image filters and frequency separation", "d": "Converts an RGB image to separate L, A and B channels, or rebuilds RGB from those channels when no RGB input is given. The channel outputs use raw LAB values in channel-first layout, not normal image values.", "u": "To work on brightness and color separately.", "src": "images.py:611", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Image_Channels_LAB.jpg", "j": "res4lyf_renders/nodes/Image_Channels_LAB.json", "w": "IMAGE"}, {"n": "Image Crop Location Exact", "g": "Image size and cropping", "d": "Crops an image at given x and y coordinates and size, clamped to the image's edges, and also outputs the crop details. The edge option can force a square from the shorter or longer side.", "u": "When you know the exact pixel area you want.", "src": "images.py:935", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Image_Crop_Location_Exact.jpg", "j": "res4lyf_renders/nodes/Image_Crop_Location_Exact.json", "w": "IMAGE"}, {"n": "Image Gaussian Blur", "g": "Image filters and frequency separation", "d": "Applies OpenCV gaussian blur per channel after converting to 8-bit, with a kernel of the size setting minus one.", "u": "To soften an image or make a low-pass layer.", "src": "images.py:820", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Image_Gaussian_Blur.jpg", "j": "res4lyf_renders/nodes/Image_Gaussian_Blur.json", "w": "IMAGE"}, {"n": "Image Get Color Swatches", "g": "Color-swatch masks", "d": "Reads the distinct colors in a swatch image, ignoring any color much rarer than the most common one, and lists them from top to bottom as they first appear.", "u": "To set the order of regions for the color mask nodes.", "src": "images.py:1045", "s": "ran", "e": "", "t": "", "j": "res4lyf_renders/nodes/Image_Get_Color_Swatches.json", "w": ""}, {"n": "Image Grain Add", "g": "Image filters and frequency separation", "d": "Makes the same kind of grain with fixed settings, combines it with the image in a hard light blend, and mixes the result back by a weight.", "u": "For one-slider grain control.", "src": "images.py:375", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Image_Grain_Add.jpg", "j": "res4lyf_renders/nodes/Image_Grain_Add.json", "w": "IMAGE"}, {"n": "Image Median Blur", "g": "Image filters and frequency separation", "d": "Applies OpenCV median blur per channel after converting to 8-bit, with a kernel of the size setting minus one.", "u": "To blur while keeping edges, or to make a low-pass layer.", "src": "images.py:792", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Image_Median_Blur.jpg", "j": "res4lyf_renders/nodes/Image_Median_Blur.json", "w": "IMAGE"}, {"n": "Image Pair Split", "g": "Image size and cropping", "d": "Cuts an image batch into two halves and sends each to its own output.", "u": "To separate a batch holding a pair of images.", "src": "images.py:915", "s": "error", "e": "ValueError: not enough values to unpack (expected 2, got 1)\n", "t": "", "j": "res4lyf_renders/nodes/Image_Pair_Split.json", "w": "IMAGE"}, {"n": "Image Repeat Tile To Size", "g": "Image size and cropping", "d": "Repeats an image as tiles until it covers a target size, then either crops to that size or resizes to it (default lanczos stretch).", "u": "To fill a larger canvas with a repeated image.", "src": "images.py:258", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Image_Repeat_Tile_To_Size.jpg", "j": "res4lyf_renders/nodes/Image_Repeat_Tile_To_Size.json", "w": "IMAGE"}, {"n": "Image Sharpen FS", "g": "Image filters and frequency separation", "d": "Sharpens by blurring the image (median or gaussian), taking the fine detail left over using hard or linear light math, and blending that detail back onto the original.", "u": "For sharpening based on frequency separation.", "src": "images.py:745", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Image_Sharpen_FS.jpg", "j": "res4lyf_renders/nodes/Image_Sharpen_FS.json", "w": "IMAGE"}, {"n": "Latent Batcher", "g": "Create and move", "d": "Repeats a single latent into a batch of the given size, keeping only the samples. The channel count is hard-coded to 4, so other latents will not fit.", "u": "When you want several copies of one 4-channel latent.", "src": "nodes_latents.py:754", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Latent_Batcher.jpg", "j": "res4lyf_renders/nodes/Latent_Batcher.json", "w": "LATENT"}, {"n": "Latent Channels From To", "g": "Channel edits", "d": "Replaces each channel's average in latent_to with the matching average from latent_from, leaving the variation around that average unchanged.", "u": "When you want one latent to take on another's overall channel levels.", "src": "nodes_latents.py:638", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Latent_Channels_From_To.jpg", "j": "res4lyf_renders/nodes/Latent_Channels_From_To.json", "w": "LATENT"}, {"n": "Latent Clear State Info", "g": "Sampler state", "d": "Returns a latent containing only its samples, removing state_info and every other key such as a noise mask.", "u": "When you want the next sampler to start without any carried-over state.", "src": "nodes_latents.py:436", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Latent_Clear_State_Info.jpg", "j": "res4lyf_renders/nodes/Latent_Clear_State_Info.json", "w": "LATENT"}, {"n": "Latent CropGuides State Info", "g": "Sampler state", "d": "Reads the keyframe count from LTX conditioning, removes that many frames from the end of the video latent, its noise mask and matching state_info tensors, and clears the keyframe data from the conditioning and any stored guider. It can take the conditioning from the stored guider if none is connected, and it is flagged experimental.", "u": "When you strip LTX guide frames from a latent that still carries sampler state.", "src": "nodes_latents.py:291", "s": "error", "e": "ValueError: not enough values to unpack (expected 5, got 4)\n", "t": "", "j": "res4lyf_renders/nodes/Latent_CropGuides_State_Info.json", "w": "CONDITIONING"}, {"n": "Latent Display State Info", "g": "Sampler state", "d": "Lists everything in a latent's state_info as text, showing shape, type, mean and spread for tensors, and shows the text on the node as well as outputting it. If there is none it reports that.", "u": "When you want to inspect what a sampler left in a latent.", "src": "nodes_latents.py:512", "s": "ran", "e": "", "t": "", "j": "res4lyf_renders/nodes/Latent_Display_State_Info.json", "w": ""}, {"n": "Latent Extract State Info", "g": "Sampler state", "d": "Pulls values out of state_info as separate outputs: the sigmas, the sigmas still left after end_step, sigma_next, end_step, sampler_mode and whether the run completed. It strips the zero padding the samplers add to unsample and resample schedules.", "u": "When you want to continue from where a previous sampler stopped using its own schedule.", "src": "nodes_latents.py:565", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Latent_Extract_State_Info.jpg", "j": "res4lyf_renders/nodes/Latent_Extract_State_Info.json", "w": "SIGMAS"}, {"n": "Latent Get Channel Means", "g": "Channel edits", "d": "Averages a latent over its height and width to get one number per channel and returns them as a SIGMAS-type list. With a batch larger than one, the result has a row per batch item.", "u": "When you want a latent's per-channel averages as numbers to pass along.", "src": "nodes_latents.py:662", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Latent_Get_Channel_Means.jpg", "j": "res4lyf_renders/nodes/Latent_Get_Channel_Means.json", "w": "SIGMAS"}, {"n": "Latent Match Channelwise", "g": "Channel edits", "d": "Intended to shift a target latent's channels to match a source latent's mean, and optionally spread, inside masked areas, with extra_options flags for changing the behavior. As written it reads exclude_channels before assigning it at line 2566, which raises an error, and its optional masks and extra_options have no default values in the function signature.", "u": "", "src": "nodes_latents.py:2531", "s": "error", "e": "TypeError: latent_channelwise_match.main() missing 3 required positional arguments: 'mask_target', 'mask_source', and 'extra_options'\n", "t": "", "j": "res4lyf_renders/nodes/Latent_Match_Channelwise.json", "w": "LATENT"}, {"n": "Latent Normalize Channels", "g": "Channel edits", "d": "Normalizes (mean 0, spread 1), centers (mean 0) or standardizes (spread 1) a latent, either across the whole tensor or separately for each channel of each batch item. In channels mode it changes the input tensor directly, and the output keeps only the samples.", "u": "When you want to reset a latent's mean or spread.", "src": "nodes_latents.py:2481", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Latent_Normalize_Channels.jpg", "j": "res4lyf_renders/nodes/Latent_Normalize_Channels.json", "w": "LATENT"}, {"n": "Latent Replace State Info", "g": "Sampler state", "d": "Overwrites start_step, end_step, raw_x or sigmas in state_info, each behind its own on/off switch, and removes the entry if the switch is on but the matching input is empty. The raw_x input is stored as the whole connected latent object, not just its tensor, while the sampler reads raw_x as a tensor.", "u": "When you want to change where a chained sampler resumes.", "src": "nodes_latents.py:459", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Latent_Replace_State_Info.jpg", "j": "res4lyf_renders/nodes/Latent_Replace_State_Info.json", "w": "LATENT"}, {"n": "Latent to Cuda", "g": "Create and move", "d": "Moves a latent to the GPU or CPU, either every tensor nested anywhere inside it or just the samples. In full mode everything that is not a tensor is deep-copied.", "u": "When you need to control which device a latent and its stored state sit on.", "src": "nodes_latents.py:687", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Latent_to_Cuda.jpg", "j": "res4lyf_renders/nodes/Latent_to_Cuda.json", "w": "LATENT"}, {"n": "Latent to RawX", "g": "Sampler state", "d": "Copies the latent's current samples into state_info as raw_x, in 64-bit. The pack's sampler uses raw_x in place of the latent in unsample and resample modes when the shapes match.", "u": "When you edited a latent and want the sampler's next unsample or resample run to start from that edit.", "src": "nodes_latents.py:241", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Latent_to_RawX.jpg", "j": "res4lyf_renders/nodes/Latent_to_RawX.json", "w": "LATENT"}, {"n": "Latent Transfer State Info", "g": "Sampler state", "d": "Gives one latent a deep copy of another latent's state_info while keeping its own samples. The source latent must have state_info or the node fails.", "u": "When you processed a latent separately and need to restore its sampler state.", "src": "nodes_latents.py:610", "s": "error", "e": "KeyError: 'state_info'\n", "t": "", "j": "res4lyf_renders/nodes/Latent_Transfer_State_Info.json", "w": "LATENT"}, {"n": "Latent TrimVideo State Info", "g": "Sampler state", "d": "Removes frames from the start of a video latent, and also from every tensor of the same shape stored in its state_info so they stay aligned. Adapted from a ComfyUI core node, as a code comment says, and flagged experimental.", "u": "When you trim a video latent that will go back into a chained sampler.", "src": "nodes_latents.py:266", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Latent_TrimVideo_State_Info.jpg", "j": "res4lyf_renders/nodes/Latent_TrimVideo_State_Info.json", "w": "LATENT"}, {"n": "Latent Upscale State Info", "g": "Sampler state", "d": "Rescales a latent by a factor using a chosen method and applies the same resize to matching tensors in state_info. The helper it uses only changes tensors with 5 or more dimensions, so an ordinary 4-dimensional image latent passes through at its original size.", "u": "When you upscale a video latent that will go back into a chained sampler.", "src": "nodes_latents.py:412", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Latent_Upscale_State_Info.jpg", "j": "res4lyf_renders/nodes/Latent_Upscale_State_Info.json", "w": "LATENT"}, {"n": "LatentBatch_channels", "g": "Channel edits", "d": "Applies an offset, multiply or power to each of the 4 latent channels, named luminosity, cyan-red, lime-purple and pattern structure, for every item in the batch. Optional schedules are multiplied by the slider values to give each batch item its own amount.", "u": "When you want to shift or scale individual channels of a 4-channel latent.", "src": "nodes_latents.py:2239", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/LatentBatch_channels.jpg", "j": "res4lyf_renders/nodes/LatentBatch_channels.json", "w": "LATENT"}, {"n": "LatentBatch_channels_16", "g": "Channel edits", "d": "Does the same offset, multiply or power per channel and per batch item, but for 16-channel latents with numbered channels. The sliders default to 0, so multiply zeroes a channel and power turns it to ones unless the values are changed.", "u": "When you want to adjust individual channels of a 16-channel latent.", "src": "nodes_latents.py:2329", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/LatentBatch_channels_16.jpg", "j": "res4lyf_renders/nodes/LatentBatch_channels_16.json", "w": "LATENT"}, {"n": "LatentNoiseBatch_fractal", "g": "Noise", "d": "Creates a batch of fractal noise the same size as the input latent, with alpha and k settable per item from schedules. The latent only sets the size, so its content is not added to the result, and steps defaults to 0, which gives an empty batch unless steps or steps_ is set.", "u": "When you want a batch of noise with a chosen frequency falloff.", "src": "nodes_latents.py:2185", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/LatentNoiseBatch_fractal.jpg", "j": "res4lyf_renders/nodes/LatentNoiseBatch_fractal.json", "w": "LATENT"}, {"n": "LatentNoiseBatch_gaussian", "g": "Noise", "d": "Creates a batch of Gaussian noise the same size as the input latent, without adding the latent's content. The mean and std inputs are stored on the generator but its generate method ignores them, so every item comes out normalized to mean 0 and spread 1.", "u": "When you want a batch of plain normalized Gaussian noise.", "src": "nodes_latents.py:2144", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/LatentNoiseBatch_gaussian.jpg", "j": "res4lyf_renders/nodes/LatentNoiseBatch_gaussian.json", "w": "LATENT"}, {"n": "LatentNoiseBatch_gaussian_channels", "g": "Noise", "d": "Adds Gaussian noise to a 4-channel latent to make a batch, shifting each channel by its own luminosity, cyan-red, lime-purple or pattern value per item. The overall mean and std inputs have no effect because the generator ignores them, and with steps at 0 the means schedule must be connected.", "u": "When you want noisy copies of a latent with a color or brightness bias per channel.", "src": "nodes_latents.py:2073", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/LatentNoiseBatch_gaussian_channels.jpg", "j": "res4lyf_renders/nodes/LatentNoiseBatch_gaussian_channels.json", "w": "LATENT"}, {"n": "LatentNoiseBatch_perlin", "g": "Noise", "d": "Builds a new 4-channel noise latent at one eighth of the given size, starting from Perlin noise, scrambling it with a remainder step and reshaping the values to a bell curve clamped to plus or minus 5. The detail setting scales the result slightly, and no input latent is used.", "u": "", "src": "nodes_latents.py:1997", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/LatentNoiseBatch_perlin.jpg", "j": "res4lyf_renders/nodes/LatentNoiseBatch_perlin.json", "w": "LATENT"}, {"n": "LatentNoised", "g": "Noise", "d": "Adds noise to a latent, either generated from a chosen noise type and seed or taken from a connected latent, scaled by a strength value and optionally limited by a mask. It can also rescale the noise to the latent's mean and spread, or blend the latent into the noise and renormalize.", "u": "When you want a latent with a controlled amount of a specific kind of noise added.", "src": "nodes_latents.py:64", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/LatentNoised.jpg", "j": "res4lyf_renders/nodes/LatentNoised.json", "w": "LATENT"}, {"n": "LatentNoiseList", "g": "Noise", "d": "Adds fractal noise to a latent repeatedly and outputs the results as a list of separate latents rather than one batch. Each item can have its own alpha and k from optional schedules, and with steps at 0 the count comes from the alphas schedule.", "u": "When you want a list of noisy variations of one latent.", "src": "nodes_latents.py:161", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/LatentNoiseList.jpg", "j": "res4lyf_renders/nodes/LatentNoiseList.json", "w": "LATENT"}, {"n": "LatentPhaseMagnitude", "g": "Frequency edits", "d": "Meant to convert two latents to the frequency domain with a 64-bit FFT and blend their phase and magnitude separately for each of 4 channels, then convert back. As written the function requires a latent_1_repeat argument the node does not declare, and its normalize options call a class rather than a function, so both look like they would raise errors.", "u": "", "src": "nodes_latents.py:1171", "s": "error", "e": "TypeError: LatentPhaseMagnitude.main() missing 1 required positional argument: 'latent_1_repeat'\n", "t": "", "j": "res4lyf_renders/nodes/LatentPhaseMagnitude.json", "w": "LATENT"}, {"n": "LatentPhaseMagnitudeMultiply", "g": "Frequency edits", "d": "Converts a latent to the frequency domain with a 64-bit FFT, multiplies phase and magnitude by a value per channel, and converts back, with defaults of 1.0 leaving it unchanged. Only the first 4 channels are processed, any further channels come out as zero, and turning on a normalize option looks like it would raise an error because the name points at a class.", "u": "When you want to scale a latent's phase or magnitude channel by channel.", "src": "nodes_latents.py:1391", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/LatentPhaseMagnitudeMultiply.jpg", "j": "res4lyf_renders/nodes/LatentPhaseMagnitudeMultiply.json", "w": "LATENT"}, {"n": "LatentPhaseMagnitudeOffset", "g": "Frequency edits", "d": "Works like the multiply version but adds a value per channel to phase and magnitude. The defaults are 1.0, so the untouched settings do change the latent, and the same 4-channel limit and normalize problem apply.", "u": "When you want to shift a latent's phase or magnitude channel by channel.", "src": "nodes_latents.py:1523", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/LatentPhaseMagnitudeOffset.jpg", "j": "res4lyf_renders/nodes/LatentPhaseMagnitudeOffset.json", "w": "LATENT"}, {"n": "LatentPhaseMagnitudePower", "g": "Frequency edits", "d": "Works like the multiply version but raises phase and magnitude to a power per channel, with defaults of 1.0 leaving it unchanged. Phase values can be negative and the code has no guard for fractional powers of them, and the same 4-channel limit and normalize problem apply.", "u": "When you want to apply a power curve to a latent's phase or magnitude.", "src": "nodes_latents.py:1655", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/LatentPhaseMagnitudePower.jpg", "j": "res4lyf_renders/nodes/LatentPhaseMagnitudePower.json", "w": "LATENT"}, {"n": "LatentUpscaleWithVAE", "g": "VAE and images", "d": "Decodes a latent to pixels, resizes it with lanczos to the given size and encodes it again with a fixed seed of 42. If the latent has state_info it uses the stored denoised result and also re-encodes the stored previous-step data, so a chained sampler receives them at the new size.", "u": "When you want a pixel-space upscale that also carries multistep sampler state.", "src": "helper_sigma_preview_image_preproc.py:618", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/LatentUpscaleWithVAE.jpg", "j": "res4lyf_renders/nodes/LatentUpscaleWithVAE.json", "w": "LATENT"}, {"n": "LayerPatcher", "g": "Swap and save weights", "d": "Loads three weight files and writes them directly into a model: its input embedder, any layers named in the gates file, and its final layer, all at the chosen precision. It changes the loaded model in place rather than a copy, has no option to skip a file, and has a commented-out Retrojector option.", "u": "", "src": "loaders.py:382", "s": "error", "e": "AttributeError: 'UNetModel' object has no attribute 'x_embedder'\n", "t": "", "j": "res4lyf_renders/nodes/LayerPatcher.json", "w": "MODEL"}, {"n": "Legacy_ClownSampler", "g": "Legacy samplers and options", "d": "Deprecated. Builds a sampler object for the old legacy_rk Runge-Kutta sampler, with settings for SDE noise, implicit steps, CFG++ and latent guides.", "u": "For older workflows; the README says previous versions stay available with Legacy prepended.", "src": "legacy/legacy_samplers.py:378", "s": "error", "e": "TypeError: legacy_sample_rk() got an unexpected keyword argument 'outer_sigmas_len'\n", "t": "", "j": "res4lyf_renders/nodes/Legacy_ClownSampler.json", "w": "SAMPLER"}, {"n": "Legacy_ClownsharKSampler", "g": "Legacy samplers and options", "d": "Deprecated. An all-in-one old sampler that applies model shift for SD3, AuraFlow, Stable Cascade and Flux, prepares noise and sigmas, and runs legacy_rk with optional guides and options.", "u": "For older workflows.", "src": "legacy/legacy_samplers.py:97", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Legacy_ClownsharKSampler.jpg", "j": "res4lyf_renders/nodes/Legacy_ClownsharKSampler.json", "w": "LATENT"}, {"n": "Legacy_ClownsharKSamplerGuides", "g": "Legacy samplers and options", "d": "Deprecated. Packages guide latents, a mask, a guide mode and weight settings into a GUIDES value for the old sampler.", "u": "For older workflows using latent guides.", "src": "legacy/legacy_samplers.py:444", "s": "error", "e": "AttributeError: 'tuple' object has no attribute 'get'\n", "t": "", "j": "res4lyf_renders/nodes/Legacy_ClownsharKSamplerGuides.json", "w": "GUIDES"}, {"n": "Legacy_SharkSampler", "g": "Legacy samplers and options", "d": "Deprecated. Runs sampling with a supplied sampler: it builds sigmas and starting noise, supports unsample and resample modes, can truncate conditioning, and returns normal and 64-bit outputs.", "u": "For older workflows that pair it with a legacy sampler node.", "src": "legacy/legacy_samplers.py:494", "s": "error", "e": "RuntimeError: Input type (double) and bias type (float) should be the same\n", "t": "", "j": "res4lyf_renders/nodes/Legacy_SharkSampler.json", "w": "LATENT"}, {"n": "Linear Quadratic Advanced", "g": "Schedule makers", "d": "Calls ComfyUI's linear-quadratic scheduler for the connected model, exposing how far through the linear part runs (inflection_percent) and the noise threshold where it ends. Denoise works by building a longer schedule and keeping the end of it.", "u": "To adjust the linear-quadratic schedule's two internal settings.", "src": "sigmas.py:1208", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Linear_Quadratic_Advanced.jpg", "j": "res4lyf_renders/nodes/Linear_Quadratic_Advanced.json", "w": "SIGMAS"}, {"n": "Mask Bounding Box Aspect Ratio", "g": "Mask tools", "d": "Finds the box around a mask, adds padding, and grows the box to a chosen aspect ratio, then crops the image and mask to it. It also outputs a version of the mask faded outward only, plus the crop's x, y, width and height; a code comment says it is based on ComfyUI_essentials.", "u": "To crop to a masked area at a set shape, for example before working on just that region.", "src": "images.py:1442", "s": "error", "e": "TypeError: MaskBoundingBoxAspectRatio.execute() missing 1 required positional argument: 'mask'\n", "t": "", "j": "res4lyf_renders/nodes/Mask_Bounding_Box_Aspect_Ratio.json", "w": "IMAGE"}, {"n": "Mask Sketch", "g": "Mask tools", "d": "Shows an image-file picker, but the code that runs ignores the chosen file and returns a fixed 512x512 white image with an empty mask. The real loader remains as an unused method, load_image_orig, so this node looks unfinished.", "u": "", "src": "images.py:1348", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/Mask_Sketch.jpg", "j": "res4lyf_renders/nodes/Mask_Sketch.json", "w": "IMAGE"}, {"n": "MaskEdge", "g": "Mask tools", "d": "Makes a band around a mask's outline, with separate multipliers for how far it reaches inside and outside. Width is either in pixels or a percent of the square root of the mask's area, and a side whose width comes to zero uses that whole side instead of a band.", "u": "When you need to target only the area around a mask's edge.", "src": "nodes_latents.py:808", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/MaskEdge.jpg", "j": "res4lyf_renders/nodes/MaskEdge.json", "w": "MASK"}, {"n": "MaskFloatToBoolean", "g": "Mask tools", "d": "Turns any non-zero mask value into 1 and leaves zeros as 0, keeping the original number type.", "u": "When a soft mask needs hard edges.", "src": "nodes_latents.py:781", "s": "rendered", "e": "", "t": "res4lyf_renders/nodes/MaskFloatToBoolean.jpg", "j": "res4lyf_renders/nodes/MaskFloatToBoolean.json", "w": "MASK"}, {"n": "Masks From Color Swatches", "g": "Color-swatch masks", "d": "Splits a multicolor painted image into one mask per swatch color, allowing small color differences and sending near-matching painted pixels to the nearest swatch. It then removes small specks and gives leftover pixels to the mask with the most neighbors around them.", "u": "To turn one painted color map into many region masks.", "src": "images.py:1066", "s": "needs", "e": "needs COLOR_SWATCHES", "t": "", "j": "", "w": ""}, {"n": "Masks From Colors", "g": "Color-swatch masks", "d": "Does both swatch steps in one node: reads colors from a swatch image, then splits the painted image into masks. Unlike Masks From Color Swatches, it also removes any masks that end up empty.", "u": "To go straight from a swatch image and a painted map to masks.", "src": "images.py:1090", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Masks Unpack 16", "g": "Color-swatch masks", "d": "Sends each mask in a batch to its own output, for up to sixteen outputs. The code does not check that the count matches.", "u": "To wire masks from the color nodes into separate regional inputs.", "src": "images.py:1023", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Masks Unpack 4", "g": "Color-swatch masks", "d": "Sends each mask in a batch to its own output, for up to four outputs. The code does not check that the count matches.", "u": "To wire masks from the color nodes into separate regional inputs.", "src": "images.py:989", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Masks Unpack 8", "g": "Color-swatch masks", "d": "Sends each mask in a batch to its own output, for up to eight outputs. The code does not check that the count matches.", "u": "To wire masks from the color nodes into separate regional inputs.", "src": "images.py:1006", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "MaskToggle", "g": "Mask tools", "d": "Passes a mask through when enabled and outputs nothing (None) when disabled.", "u": "To switch a mask on or off without rewiring.", "src": "nodes_latents.py:216", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "ModelSamplingAdvanced", "g": "Timestep shift", "d": "Replaces the model's sampling object and rebuilds its sigma table from a shift value, using exponential or linear scaling. It supports Flux, Chroma, AuraFlow, SD3, HiDream, HunyuanVideo, WAN, Cosmos and LTXV, and raises an error for anything else.", "u": "Use it to set shift by hand and choose the scaling; a code comment says exponential is the default for SD3.5M and Flux, linear for SD3.5L.", "src": "models.py:1045", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "ModelSamplingAdvancedResolution", "g": "Timestep shift", "d": "Works like ModelSamplingAdvanced but calculates the shift from a latent's height and width using max_shift and base_shift. It reads the size from the latent tensor, and its formula divides by 8*8*2*2, the same divisor ComfyUI's own Flux node applies to pixel sizes, so the result differs from that node for the same image.", "u": "Use it when shift should follow the latent's size.", "src": "models.py:1147", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "ModelTimestepPatcher", "g": "Timestep shift", "d": "Another registered name for the same class as ModelSamplingAdvanced, so it behaves identically. It rebuilds the model's sigma table from a shift value using exponential or linear scaling.", "u": "", "src": "models.py:1045", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "PrepForUnsampling", "g": "VAE and images", "d": "The same class as VAEEncodeAdvanced registered under a second name, so it behaves identically.", "u": "", "src": "__init__.py:184", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "ReAuraPatcher", "g": "Regional and style patchers", "d": "Switches an AuraFlow model, its layers and their attention to the pack's versions on all layers, and adds StyleWCT and Retrojector objects. It accepts only AuraFlow.", "u": "Use it before regional or style-guided AuraFlow sampling.", "src": "models.py:939", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "ReAuraPatcherAdvanced", "g": "Regional and style patchers", "d": "The AuraFlow patcher with comma-separated lists of which double and single layers use regional masks. Left-out single layers ignore the mask, but the stand-in for left-out double layers does not match how those layers call it, so a partial double list looks like it would raise an error; this was not run.", "u": "Use it to limit regional masks to some AuraFlow layers.", "src": "models.py:883", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "ReChromaPatcher", "g": "Regional and style patchers", "d": "Does the same job as ReFluxPatcher for Chroma models, on all blocks, and adds the StyleWCT and Retrojector objects. It accepts only Chroma.", "u": "Use it before regional or style-guided Chroma sampling.", "src": "models.py:486", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "ReChromaPatcherAdvanced", "g": "Regional and style patchers", "d": "The Chroma patcher with comma-separated lists of which double and single blocks use regional masks; the value all covers every block. From reading the code, the stand-in class used for left-out blocks only accepts (c, mask) while the model calls blocks with other arguments, so a partial list looks like it would raise an error; this was not run.", "u": "Use it to try limiting regional masks to some Chroma blocks.", "src": "models.py:432", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "ReFluxPatcher", "g": "Regional and style patchers", "d": "Switches a Flux model to the pack's versions of its model and blocks for all blocks, which can use regional masks and style guides. It also adds a StyleWCT object and a Retrojector, which is a pseudo-inverse of the model's input layer used to move data back out of the model's embedding space.", "u": "Use it before regional or style-guided Flux sampling.", "src": "models.py:358", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "ReFluxPatcherAdvanced", "g": "Regional and style patchers", "d": "The Flux patcher with comma-separated lists of which double and single blocks use regional masks; the value all covers every block. From reading the code, the stand-in class used for left-out blocks only accepts (c, mask) while the model calls blocks with other arguments, so a partial list looks like it would raise an error; this was not run.", "u": "Use it to try limiting regional masks to some Flux blocks.", "src": "models.py:303", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "ReHiDreamPatcher", "g": "Regional and style patchers", "d": "Switches a HiDream model and all its blocks, attention, feed-forward and gate parts to the pack's versions, and adds StyleWCT, WaveletStyleWCT and Retrojector objects. It also converts the final layer's weights to bfloat16 and attaches a shared sort_buffer dictionary, which nothing else in the pack's Python references.", "u": "Use it before regional or style-guided HiDream sampling.", "src": "models.py:780", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "ReHiDreamPatcherAdvanced", "g": "Regional and style patchers", "d": "The HiDream patcher with comma-separated lists of which double and single stream blocks use regional masks; the value all covers every block. From reading the code, the stand-in class used for left-out blocks only accepts (c, mask) while the model calls blocks with other arguments, so a partial list looks like it would raise an error; this was not run.", "u": "Use it to try limiting regional masks to some HiDream blocks.", "src": "models.py:667", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "ReLTXVPatcher", "g": "Regional and style patchers", "d": "Switches an LTXV model's top-level class to the pack's version and adds StyleWCT and Retrojector objects; it does not change individual blocks. The pack's LTXV model has style-guide code but no regional mask code, and the README lists LTXV under style transfer only, though the node's error text says regional.", "u": "Use it before style-guided LTXV sampling.", "src": "models.py:565", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "ReLTXVPatcherAdvanced", "g": "Regional and style patchers", "d": "Does the same as ReLTXVPatcher. Its doublestream_blocks and singlestream_blocks inputs are read but never used to choose blocks, so they have no effect unless their text fails to parse.", "u": "", "src": "models.py:521", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "ReReduxPatcher", "g": "Regional and style patchers", "d": "Makes a deep copy of a Flux Redux style model and switches the copy to the pack's encoder class, whose extra feature_match method is what the pack's StyleModelApplyStyle node calls. The class is marked experimental.", "u": "Use it to prepare a Redux model for StyleModelApplyStyle.", "src": "models.py:384", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "ReSD35Patcher", "g": "Regional and style patchers", "d": "Switches an SD3.5 model and all its joint blocks to the pack's versions and adds StyleWCT and Retrojector objects. It accepts only SD3.5.", "u": "Use it before regional or style-guided SD3.5 sampling.", "src": "models.py:855", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "ReSD35PatcherAdvanced", "g": "Regional and style patchers", "d": "The SD3.5 patcher with a comma-separated list of joint blocks to switch; the value all covers every block. Left-out blocks stay as ComfyUI's JointBlock, but the pack's model still passes them a mask argument, so from reading this box's ComfyUI core a partial list looks like it would raise an error; this was not run.", "u": "Use it to try limiting the patch to some SD3.5 joint blocks.", "src": "models.py:807", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "ReSDPatcher", "g": "Regional and style patchers", "d": "Walks the input, middle and output blocks of an SD1.5 or SDXL UNet and switches its transformer, attention and ResBlock parts to the pack's versions. It adds StyleWCT and a Retrojector built from the first input layer, and has no Advanced version.", "u": "Use it before regional or style-guided SD1.5 or SDXL sampling.", "src": "models.py:590", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "ReWanPatcher", "g": "Regional and style patchers", "d": "Switches a WAN model to the pack's versions of its model, blocks and attention layers for all blocks, which can use regional masks and style guides from other nodes. It accepts only WAN, and the off switch returns a plain copy. Unlike the patchers for other models, it does not add a Retrojector or StyleWCT object.", "u": "Use it before regional or style-guided WAN sampling; the README lists WAN for both.", "src": "models.py:276", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "ReWanPatcherAdvanced", "g": "Regional and style patchers", "d": "The WAN patcher with lists of which blocks get the mask-aware self-attention and cross-attention; other blocks get plain self-attention or keep their original cross-attention. It can also make each frame attend only to a window of nearby frames, either stopping at the ends of the clip (standard) or wrapping around (circular), with window size set by sliding_window_frames divided by 4.", "u": "Use it to limit regional masks to some WAN blocks, or to use windowed self-attention on long clips.", "src": "models.py:200", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "SamplerOptions_GarbageCollection", "g": "Legacy samplers and options", "d": "Deprecated. Copies a sampler and sets a flag to clean up memory after each step, trading speed for fewer out-of-memory errors according to its description. Only legacy_rk acts on the flag in the code; the newer rk sampler accepts it without using it.", "u": "With the oldest legacy sampler when memory runs short on large models.", "src": "legacy/samplers_extensions.py:66", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "SamplerOptions_TimestepScaling", "g": "Legacy samplers and options", "d": "Deprecated. Copies a sampler and sets custom formulas for converting between sigma and timestep. Its description says this lets you pick Runge-Kutta midpoints with different scaling.", "u": "To try different RK midpoint scaling in older workflows.", "src": "legacy/samplers_extensions.py:33", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "SD35Loader", "g": "Loaders", "d": "Loads an SD3.5 model with up to three text encoders and a VAE, treating the encoders as SD3 type. It also sets the seed to 42 first, and can take the encoders and VAE from a checkpoint.", "u": "Use it to load an SD3.5 setup from one node.", "src": "loaders.py:277", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "SeedGenerator", "g": "Text and seeds", "d": "Outputs the seed you enter and that seed plus one.", "u": "When two parts of a workflow need related but different seeds.", "src": "nodes_misc.py:373", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Set Precision", "g": "Precision", "d": "Converts a latent to 16, 32 or 64-bit floats and can also set that as PyTorch's global default number type. The output holds only the samples, so any other latent data such as a noise mask is dropped.", "u": "When you want a latent at a chosen precision before sampling.", "src": "nodes_precision.py:5", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Set Precision Advanced", "g": "Precision", "d": "Always sets PyTorch's global default type from global_precision and the pack's shared cast type from shark_precision. It also outputs the latent unchanged, cast to the global type, and as separate 16, 32 and 64-bit copies.", "u": "When PyTorch's default type and the pack's internal cast type need different settings.", "src": "nodes_precision.py:123", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Set Precision Universal", "g": "Precision", "d": "Converts any connected positive and negative conditioning, sigmas and latent to bf16, fp16, fp32 or fp64, or passes them through untouched, and can set the global default type. For conditioning it only handles the first entry and expects a pooled_output to be present.", "u": "When you want one node to set precision on all the sampler inputs together.", "src": "nodes_precision.py:47", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "SetImageSize", "g": "Image size and cropping", "d": "Outputs the width and height numbers you enter.", "u": "To set one size for several nodes.", "src": "nodes_misc.py:8", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "SetImageSizeWithScale", "g": "Image size and cropping", "d": "Outputs a width and height plus those values multiplied by a scale and rounded down to whole numbers.", "u": "When one size setting should feed both a base and a scaled pass.", "src": "nodes_misc.py:31", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "SharkChainsampler_Beta", "g": "Samplers", "d": "Continues from an earlier sampler's output by running SharkSampler with the schedule and step count stored in the latent, using seed -1. It can reuse the sampler carried in the latent, and its mode is unsample or resample.", "u": "To run the next stage after an earlier sampler node with a connected sampler.", "src": "beta/samplers.py:1127", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "SharkOptions_Beta", "g": "General options", "d": "Stores settings for the starting noise (type and strength), an alternate denoise value that multiplies the sigma schedule, and a channelwise CFG switch, for a sampler node to read.", "u": "When you want a different starting noise type or the multiply-style denoise.", "src": "beta/samplers_extensions.py:892", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "SharkOptions_GuideCond_Beta", "g": "General options", "d": "Stores a separate positive, negative and CFG for model calls made on the guide path (latent type yt) in flow and sync modes.", "u": "When the guide path needs its own prompt or CFG.", "src": "beta/samplers_extensions.py:806", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "SharkOptions_GuideConds_Beta", "g": "General options", "d": "Same as SharkOptions Guide Cond, with separate conditioning and CFG for the masked and unmasked guides.", "u": "When masked and unmasked guides need different prompts or CFG.", "src": "beta/samplers_extensions.py:844", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "SharkOptions_GuiderInput", "g": "General options", "d": "Stores an external ComfyUI guider in the options. The sampler then takes its model, CFG and conditioning from that guider, and logs a warning that flow guide mode does not work with it.", "u": "When conditioning or CFG comes from another guider node.", "src": "beta/samplers_extensions.py:2715", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "SharkOptions_StartStep_Beta", "g": "General options", "d": "Sets the step number where sampling begins, overriding the start step worked out from chained state.", "u": "When a run should begin at a specific step.", "src": "beta/samplers_extensions.py:574", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "SharkOptions_UltraCascade_Latent_Beta", "g": "General options", "d": "Stores a latent width and height that the sampler uses for UltraCascade model stages, including the size of the empty starting latent.", "u": "With UltraCascade workflows.", "src": "beta/samplers_extensions.py:932", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "SharkSampler_Beta", "g": "Samplers", "d": "Runs sampling with a sampler you connect, or one carried in the latent, using its own scheduler, steps, denoise, CFG and seed. It can sample, unsample or resample, and outputs the result, the denoised result and the options.", "u": "When the sampler settings are built separately, such as with ClownSampler.", "src": "beta/samplers.py:1015", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Abs", "g": "Arithmetic", "d": "Makes every value positive.", "u": "To remove negative values.", "src": "sigmas.py:714", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas AdaptiveNoiseFloor", "g": "Floors and cleanup", "d": "For each step, looks at the original values just before it and sets a minimum from min_noise_level plus a share of their variance divided by their mean, then raises the step if it is below that. A closing 0 is raised too.", "u": "", "src": "sigmas.py:3416", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas AdaptiveStep", "g": "Reshaping curves", "d": "Builds new values whose spacing is tighter where the schedule changes fastest, sits far from its mean, or is most crowded, depending on the mode. As written, curvature mode pads a 1D tensor in a way torch rejects, so it would raise an error, and the target_steps resampling blends a value with itself rather than with its neighbour.", "u": "", "src": "sigmas.py:1937", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Add", "g": "Arithmetic", "d": "Adds a number to every value.", "u": "To shift a whole schedule up or down.", "src": "sigmas.py:674", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Append", "g": "Cutting and joining", "d": "Adds a chosen value to the end a set number of times, then optionally adds a second schedule after that.", "u": "To extend a schedule with repeated values.", "src": "sigmas.py:2838", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas ArcCosine", "g": "Arithmetic", "d": "Clamps values to between -1 and 1, takes the arccosine, and can rescale the result to out_min and out_max. The normalize_input switch makes no difference, since both branches do the same clamp.", "u": "", "src": "sigmas.py:2873", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas ArcSine", "g": "Arithmetic", "d": "Clamps values to between -1 and 1, takes the arcsine, and can rescale the result to out_min and out_max. The normalize_input switch makes no difference, since both branches do the same clamp.", "u": "", "src": "sigmas.py:2766", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas ArcTangent", "g": "Arithmetic", "d": "Takes the arctangent of each value and can rescale the result to out_min and out_max.", "u": "", "src": "sigmas.py:2911", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Attractor", "g": "Chaos and science-themed curves", "d": "Uses the schedule and shifted copies of it as x, y, z starting points, runs Lorenz, Rossler, Aizawa, Chen or Thomas equations for a few small steps, and returns one component or the magnitude.", "u": "", "src": "sigmas.py:2202", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas CatmullRom", "g": "Reshaping curves", "d": "Draws a smooth spline through the schedule and samples it at a chosen number of points, using plain linear interpolation for fewer than 4 values. As written, a final 0.5 factor makes the spline output half the size of the input values; rescale it afterwards if that isn't wanted.", "u": "", "src": "sigmas.py:2301", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Chaos", "g": "Chaos and science-themed curves", "d": "Runs a chaotic map (logistic, simplified henon, tent, sine or cubic) for a set number of rounds, starting from the schedule's values or, by default, from each step's position. In the default case the input's values only set the output range, and the result is not a falling curve.", "u": "", "src": "sigmas.py:2058", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Cleanup", "g": "Floors and cleanup", "d": "Removes values below sigmin, collapses runs of identical values, and adds a 0 at the end.", "u": "To tidy a schedule that has been edited so it ends in 0 again.", "src": "sigmas.py:582", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas CNFInverse", "g": "Reshaping curves", "d": "Resamples a schedule to time_steps values by reading along it on a linear, quadratic, sigmoid or exponential curve, optionally backwards. Despite the name, it uses a fixed curve, with no network or differential equation.", "u": "", "src": "sigmas.py:3646", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas CollatzIteration", "g": "Chaos and science-themed curves", "d": "Applies the Collatz rule (halve if even, 3n + 1 if odd) to scaled values for a set number of rounds. Because values are decimals, almost none count as even, so nearly all take the 3n + 1 branch.", "u": "", "src": "sigmas.py:3455", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Concat", "g": "Cutting and joining", "d": "Joins two schedules end to end.", "u": "To chain two schedules into one.", "src": "sigmas.py:365", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas ConwaySequence", "g": "Chaos and science-themed curves", "d": "Makes a list from a number sequence (look-and-say term lengths, an audioactive-style digit count, paper folding or Thue-Morse) and can scale it to a range. It takes no schedule input, the result does not fall steadily, and it can be shorter than steps.", "u": "", "src": "sigmas.py:3496", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Count", "g": "Viewing and counting", "d": "Outputs how many values are in the schedule as an integer.", "u": "To feed a schedule's length into another node.", "src": "sigmas.py:802", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas CrossProduct", "g": "Arithmetic", "d": "Treats the first three values of each schedule as 3D vectors and returns their cross product, always three values. Shorter inputs are padded with zeros and later values are ignored.", "u": "", "src": "sigmas.py:2942", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas DeleteBelowFloor", "g": "Floors and cleanup", "d": "Removes every value below floor, which also removes a closing 0 unless floor is 0 or lower.", "u": "To remove the lowest steps of a schedule.", "src": "sigmas.py:517", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas DeleteDuplicates", "g": "Floors and cleanup", "d": "Removes a value when the next value is identical, so runs of repeats collapse to one. Repeats that aren't next to each other stay.", "u": "To remove repeated steps after joining or clamping schedules.", "src": "sigmas.py:560", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas DotProduct", "g": "Arithmetic", "d": "Multiplies two schedules value by value and adds the results up, returning a single number, using only as many values as the shorter one has. It can normalize both first.", "u": "", "src": "sigmas.py:2980", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Easing", "g": "Reshaping curves", "d": "Applies an animation-style easing curve (sine, quad, cubic, quart, quint, expo, circ, back, elastic or bounce; in, out or both) to the values, after raising them to the strength power. A code comment above this group of nodes names Adam Kormendi and says they were inspired by Unreal Engine maths.", "u": "To reshape a schedule with familiar animation curves.", "src": "sigmas.py:1479", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Fmod", "g": "Arithmetic", "d": "Gives the remainder of each value after dividing by divisor, using torch.fmod, where the result takes the sign of the value being divided. This is the difference from Sigmas Modulus.", "u": "", "src": "sigmas.py:3019", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Frac", "g": "Arithmetic", "d": "Keeps only the part of each value after the decimal point (value minus its floor).", "u": "", "src": "sigmas.py:3045", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas From Text", "g": "Cutting and joining", "d": "Reads numbers typed into a text box, separated by commas or spaces, and turns them into a schedule.", "u": "To hand-write an exact list of noise levels.", "src": "sigmas.py:338", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas GammaBeta", "g": "Special maths functions", "d": "Runs offset and scaled values through scipy's gamma, log-gamma, beta, incomplete gamma or incomplete beta function, turning infinite results into very large numbers, then by default stretches the result back to the input's range.", "u": "", "src": "sigmas.py:2573", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Gaussian", "g": "Reshaping curves", "d": "Applies a bell-curve operation: density, cumulative, re-centering to a new mean and spread, or fading values by distance from the mean. As written, the inverse_cdf option calls torch.sqrt on a plain number, which torch rejects, so it would raise an error.", "u": "", "src": "sigmas.py:1702", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas GaussianCDF", "g": "Reshaping curves", "d": "Runs values through the cumulative bell curve with chosen mu and sigma, which gives an S-shaped mapping, then by default stretches the result back to the input's range.", "u": "", "src": "sigmas.py:3286", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas GilbreathSequence", "g": "Chaos and science-themed curves", "d": "Starts from prime numbers, repeatedly takes absolute differences for the chosen number of levels, fills any shortfall with 1s, and can scale the result to a range. It takes no schedule input and the result does not fall steadily.", "u": "", "src": "sigmas.py:3583", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas HarmonicDecay", "g": "Schedule makers", "d": "Makes a schedule from start_value to end_value shaped by the series 1/(n + offset)^rate, with an optional closing 0.", "u": "", "src": "sigmas.py:3377", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Hyperbolic", "g": "Reshaping curves", "d": "Applies sinh, cosh, tanh or their inverses to scaled values, clamping where the inverse function isn't defined, then by default stretches the result back to the input's range.", "u": "", "src": "sigmas.py:1657", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas If", "g": "Formulas, ranges and blending", "d": "Compares each value of condition_sigmas with a threshold and takes that step from true_sigmas or false_sigmas accordingly. Inputs of different lengths are stretched to the longest with linear interpolation.", "u": "To choose between two schedules step by step.", "src": "sigmas.py:3067", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas InvLerp", "g": "Formulas, ranges and blending", "d": "Maps min_value to 0 and max_value to 1, and clamps everything outside that range.", "u": "To turn a schedule into 0-to-1 values.", "src": "sigmas.py:2737", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Iteration Karras", "g": "Schedule makers", "d": "Builds a schedule that climbs and then falls using two Karras curves, and also a momentums list that is positive on the way up and negative on the way down. If schedules are connected, the new section is added after them.", "u": "", "src": "sigmas.py:957", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Iteration Polyexp", "g": "Schedule makers", "d": "Does the same as Sigmas Iteration Karras using polyexponential curves: a climb then a fall, with a matching momentums list, added after any connected schedules.", "u": "", "src": "sigmas.py:1005", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas KernelSmooth", "g": "Reshaping curves", "d": "Smooths a schedule by averaging each value with its neighbours, using a gaussian, box, triangle, epanechnikov or cosine weighting and reflecting at the ends.", "u": "To soften sharp bumps in a schedule.", "src": "sigmas.py:1794", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas LambertW", "g": "Special maths functions", "d": "Runs scaled values through the Lambert W function one at a time, using an iterative approximation on the principal or secondary branch, then by default stretches the result back to the input's range. Inputs outside a branch's valid range are clamped.", "u": "", "src": "sigmas.py:2388", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas LangevinDynamics", "g": "Chaos and science-themed curves", "d": "Simulates a particle with friction and seeded random kicks being pulled from start_value toward end_value, and uses its path as the schedule. The last value is overwritten with end_value rather than reached by the simulation, and setting the seed also reseeds torch's global random generator.", "u": "", "src": "sigmas.py:3775", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Lerp", "g": "Formulas, ranges and blending", "d": "Blends two schedules, with t at 0 giving all of the first and t at 1 all of the second. With ensure_length on, the shorter one is stretched to match first.", "u": "To get a schedule between two others.", "src": "sigmas.py:2699", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas LinearSine", "g": "Reshaping curves", "d": "Blends the schedule with a sine wave using linear_weight. The wave is multiplied by step position, so it grows from nothing at the start to full size at the end.", "u": "To add a controlled wobble to a schedule.", "src": "sigmas.py:2804", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Logarithm2", "g": "Arithmetic", "d": "Takes the base-2 logarithm of each value, first raising tiny values to epsilon so a 0 doesn't blow up. With handle_negative on, negative values get the negated log of their size.", "u": "", "src": "sigmas.py:3129", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Math1", "g": "Formulas, ranges and blending", "d": "Runs a typed formula through Python's eval to make a schedule, where a, b, c are connected schedules, x, y, z are constants, s is the step index, and numpy and torch are available. Because the formula is executed as code, formula text in someone else's workflow should be treated as code too.", "u": "To write a custom schedule or combine schedules with a formula.", "src": "sigmas.py:821", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Math3", "g": "Formulas, ranges and blending", "d": "Does the same as Sigmas Math1 with three separate formulas and three outputs, each with its own optional rescale. The formulas run through Python's eval, so they should be treated as code.", "u": "To make three related schedules from shared inputs.", "src": "sigmas.py:882", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Modulus", "g": "Arithmetic", "d": "Gives the remainder of each value after dividing by divisor, using Python's % rule, where the result takes the divisor's sign.", "u": "", "src": "sigmas.py:634", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Mult", "g": "Arithmetic", "d": "Multiplies every value by a number, and also by a second schedule if one is connected.", "u": "To scale a schedule up or down.", "src": "sigmas.py:608", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Noise Inversion", "g": "Cutting and joining", "d": "Makes two schedules for unsampling: a flipped low-to-high one with a 0 added at the end, and the original with a 0 added at both ends. A code comment says the padding zeros stop the model's noise scaling, so it returns an epsilon prediction rather than a denoised image.", "u": "For unsampling: per the node's description, connect sigmas_fwd to the unsampling node and sigmas_rev to the sampling node after it.", "src": "sigmas.py:271", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas NormalizingFlows", "g": "Chaos and science-themed curves", "d": "Starts from a straight line and applies several seeded random affine, planar, radial or RealNVP-style transforms, then rescales so it starts and ends on the chosen values. Nothing is trained, the transforms are random, and setting the seed also reseeds torch's global random generator.", "u": "", "src": "sigmas.py:3908", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Pad", "g": "Cutting and joining", "d": "Adds one chosen value to the end of the schedule.", "u": "To add a closing value such as 0.", "src": "sigmas.py:452", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Percentile", "g": "Formulas, ranges and blending", "d": "Finds the values at two percentiles of the schedule and maps that range to target_min and target_max. Values outside the range are clipped if clip_outliers is on and left to overshoot if not.", "u": "To rescale a schedule while ignoring its extremes.", "src": "sigmas.py:1751", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas PersistentHomology", "g": "Chaos and science-themed curves", "d": "Makes a schedule from a chosen curve multiplied by a bar-count pattern built from birth and death densities; a code comment calls this a simulation, and no topology is computed from data. Because the pattern is 0 at the last step, the schedule stops short of end_value.", "u": "", "src": "sigmas.py:3844", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Power", "g": "Arithmetic", "d": "Raises every value to a chosen power.", "u": "To bend the curve of a schedule.", "src": "sigmas.py:694", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas QuantileNorm", "g": "Reshaping curves", "d": "Ranks the values and replaces each with the matching point from a target distribution: uniform, normal, exponential, logistic, or a connected reference schedule. The normal, exponential and logistic targets use unseeded random numbers, so results can differ between runs.", "u": "To make one schedule's values follow another's distribution.", "src": "sigmas.py:1859", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Quotient", "g": "Arithmetic", "d": "Divides each value by divisor and rounds down to a whole number.", "u": "", "src": "sigmas.py:654", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas ReactionDiffusion", "g": "Chaos and science-themed curves", "d": "Treats the schedule as a 1D chemical pattern and simulates Gray-Scott, FitzHugh-Nagumo or Brusselator equations for a set number of rounds with wrap-around ends, returning the first component. Gray-Scott, the default, uses fixed feed and kill rates, so param_a and param_b only affect the other two.", "u": "", "src": "sigmas.py:2122", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Recast", "g": "Precision", "d": "Converts a sigma schedule to 16, 32 or 64-bit floats and can also set that as PyTorch's global default type.", "u": "When a noise schedule needs to match the precision of the rest of the workflow.", "src": "sigmas.py:27", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Resample", "g": "Reshaping curves", "d": "Changes a schedule to a new length by linear, nearest, polynomial, exponential (log space) or power-law fitting, or by training a tiny neural network for 5000 rounds on the schedule on each run. It can then rescale the result to the original start and end; the log-based modes don't suit a schedule ending in exactly 0.", "u": "To get a schedule of the same shape with more or fewer steps.", "src": "sigmas.py:121", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Rescale", "g": "Formulas, ranges and blending", "d": "Stretches a schedule so its highest value becomes start and its lowest becomes end, which flips it if those are swapped.", "u": "Per its description, to set denoise by noise level rather than by slicing steps, or to flip a schedule.", "src": "sigmas.py:773", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas RiemannianFlow", "g": "Chaos and science-themed curves", "d": "Is meant to make a schedule from start_value to end_value along a curved-space path. As written only euclidean (a straight line) and lorentzian run: hyperbolic, the default, and spherical pass plain numbers to torch functions that reject them, so they would raise an error, and lorentzian reaches infinity at curvature 1 or above.", "u": "", "src": "sigmas.py:3705", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas SetFloor", "g": "Floors and cleanup", "d": "Replaces every value at or below floor with new_floor.", "u": "To lift or reset the lowest noise levels.", "src": "sigmas.py:493", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Sigmoid", "g": "Reshaping curves", "d": "Runs values through a logistic, tanh, softsign, hard-swish, mish or swish function after applying gain and offset, then by default stretches the result back to the input's range.", "u": "To squash a schedule into an S-curve or similar shape.", "src": "sigmas.py:1435", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas SmoothStep", "g": "Reshaping curves", "d": "Clamps values between edge0 and edge1, applies a smoothstep or smootherstep curve, and scales back to that range.", "u": "To soften the transition between two noise levels.", "src": "sigmas.py:3168", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Split", "g": "Cutting and joining", "d": "Keeps only the values from position sigmas_start up to, but not including, position sigmas_end. It returns one piece, not two.", "u": "To take a slice out of a schedule by step number.", "src": "sigmas.py:427", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Split Value", "g": "Cutting and joining", "d": "Cuts a schedule in two at a noise level instead of a step number, so the high and low outputs share the boundary value. With bias_split_up off, if the very first value is already below split_value, the low output holds only the last value.", "u": "To hand high-noise and low-noise parts of a schedule to different samplers or models.", "src": "sigmas.py:3997", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas SquareRoot", "g": "Arithmetic", "d": "Takes the square root of each value. Negative values become 0, or with handle_negative on, they get the negated root of their size.", "u": "", "src": "sigmas.py:3204", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Start", "g": "Cutting and joining", "d": "Drops the values before position sigmas_until and keeps the rest.", "u": "To begin a schedule partway through.", "src": "sigmas.py:406", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas StepwiseMultirate", "g": "Schedule makers", "d": "Makes a falling schedule from segments, where comma-separated boundaries set where each segment ends and comma-separated rates set each segment's curve (t to the power of rate). It can add a closing 0.", "u": "To give different parts of a schedule different rates of fall.", "src": "sigmas.py:3315", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas TimeStep", "g": "Reshaping curves", "d": "Builds a new rising curve from step numbers (linear, quadratic, square root or log, with optional decay) and fits it to the input's range. The input's individual values are otherwise ignored, only its length and range are used.", "u": "", "src": "sigmas.py:3243", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Truncate", "g": "Cutting and joining", "d": "Keeps the values before position sigmas_until and drops the rest.", "u": "To stop a schedule early.", "src": "sigmas.py:385", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Unpad", "g": "Cutting and joining", "d": "Removes the last value of the schedule.", "u": "To remove a closing value such as 0.", "src": "sigmas.py:473", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas Variance Floor", "g": "Floors and cleanup", "d": "Walks through the schedule and, where the next value is lower than (-1 + sqrt(1 + 4*sigma)) / 2 and above 0, raises it to that limit plus 0.001, printing each swap to the console. Its description warns that it is very hard to get close to 0 this way, because steps become very small below about sigma 0.15 to 0.2.", "u": "Per its description, to keep steps from being too large for variance-locked SDE sampling.", "src": "sigmas.py:307", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas ZetaEta", "g": "Special maths functions", "d": "Runs offset and scaled values through the Riemann zeta function (scipy) or a truncated Dirichlet eta series, then by default stretches the result back to the input's range. As written, the lerch_phi option passes two plain numbers to torch.pow, which torch rejects, so it would raise an error.", "u": "", "src": "sigmas.py:2473", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas2 Add", "g": "Arithmetic", "d": "Adds two schedules together, value by value.", "u": "To sum two schedules.", "src": "sigmas.py:753", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Sigmas2 Mult", "g": "Arithmetic", "d": "Multiplies two schedules together, value by value.", "u": "To shape one schedule with another.", "src": "sigmas.py:733", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "SigmasPreview", "g": "Viewing and counting", "d": "Draws the list of noise levels as a line graph, saves it as a temporary image and also outputs that image. With print_as_list on, it prints a table of each step's value, normalized value and step size to the console. A code comment says it was adapted from Extraltodeus's sigmas_tools_and_the_golden_scheduler.", "u": "To see the shape of a schedule before sampling with it.", "src": "helper_sigma_preview_image_preproc.py:102", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "SigmasSchedulePreview", "g": "Viewing and counting", "d": "Works out, for each step, how far a noisy (SDE) sampler would step down and how much noise it would add back for the chosen noise mode and eta, then plots those curves on a black graph with the settings written on top. It uses the connected sigmas if given, otherwise builds them from the scheduler and steps, and it has no output socket.", "u": "To compare how noise_mode, eta and scheduler settings change the steps a sampler takes.", "src": "helper_sigma_preview_image_preproc.py:695", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "StableCascade_StageB_Conditioning64", "g": "Conditioning tools", "d": "Attaches a Stage C latent to the conditioning as the Stable Cascade prior. It is wrapped in the pack's precision casting helper, which can convert tensors to a chosen float precision.", "u": "When sampling Stable Cascade Stage B from a Stage C result.", "src": "conditioning.py:381", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "StableCascade_StageC_VAEEncode_Exact", "g": "VAE and images", "d": "Resizes an image with lanczos and center crop to the given width and height times the VAE's downscale ratio, then encodes it, dropping any alpha channel. You set the size in latent units rather than pixels.", "u": "When you want a Stable Cascade Stage C latent at a specific latent size.", "src": "nodes_latents.py:1786", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "StyleModelApplyStyle", "g": "Conditioning tools", "d": "Matches the conditioning's feature statistics to a Redux image embedding using whitening-and-coloring (WCT), rather than appending the image tokens as the commented-out older code did. It calls a method only present on the pack's patched Redux encoder, the strength input is not used, and it wraps the returned tuple in another tuple.", "u": "The node description says to use it with Flux Redux.", "src": "conditioning.py:135", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Tan Scheduler", "g": "Schedule makers", "d": "Makes an S-shaped schedule from an arctangent curve, set by slope and offset and stretched between start and end, with an optional closing 0. The sgm switch adds a step and removes it again, so it doesn't change the output, and the default start and end are both 20, which gives a flat line.", "u": "", "src": "sigmas.py:1053", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Tan Scheduler 2", "g": "Schedule makers", "d": "Makes a schedule from two arctangent curves joined at a midpoint step, going from start to middle and then middle to end, each with its own slope and pivot step.", "u": "To shape the high-noise and low-noise parts of a schedule separately.", "src": "sigmas.py:1095", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "Tan Scheduler 2 Simple", "g": "Schedule makers", "d": "Makes the same two-curve schedule with pivots given as fractions of the total steps, the midpoint set to their average, and slopes adjusted for step count relative to 40 steps. The same maths is in the pack's bong_tangent scheduler; with both pivots at their default of 1 the second curve is empty, so the schedule stops at middle.", "u": "To keep a two-part curve's shape when the step count changes.", "src": "sigmas.py:1148", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "TemporalCrossAttnMask", "g": "Video frames and temporal masks", "d": "Makes a time mask that sets a start and stop frame for cross-attention only. The self-attention slot is an all-zero placeholder, which a code comment says exists to satisfy the stack.", "u": "When only the prompt's active frame range needs setting.", "src": "conditioning.py:1055", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "TemporalMaskGenerator", "g": "Video frames and temporal masks", "d": "Makes a small on/off mask over time that is on until a chosen frame and off afterward, or the reverse if inverted. Frame numbers are divided by 4 to convert to latent frames, and the node is marked experimental.", "u": "When a video prompt should switch at one frame; the README lists WAN as the temporal conditioning model.", "src": "conditioning.py:905", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "TemporalSplitAttnMask", "g": "Video frames and temporal masks", "d": "Makes a time mask with separate start and stop frames for cross-attention and self-attention, stacked into one output with cross-attention first. Frame numbers are converted to latent frames.", "u": "When the prompt and the video's self-attention should be active over different frame ranges.", "src": "conditioning.py:1003", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "TemporalSplitAttnMask (Midframe)", "g": "Video frames and temporal masks", "d": "Makes stacked cross-attention and self-attention time masks that each turn off at a chosen middle frame, with separate invert switches. It is marked experimental.", "u": "When attention should switch partway through a clip, with separate switch points.", "src": "conditioning.py:947", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "TextBox1", "g": "Text and seeds", "d": "A multiline text box that outputs what you type as one string.", "u": "When a workflow needs typed text on a wire.", "src": "nodes_misc.py:55", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "TextBox2", "g": "Text and seeds", "d": "Two multiline text boxes, each sent to its own string output unchanged.", "u": "When you want two separate prompts typed in one node.", "src": "nodes_misc.py:77", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "TextBox3", "g": "Text and seeds", "d": "Three multiline text boxes, each sent to its own string output unchanged.", "u": "When you want three separate prompts typed in one node.", "src": "nodes_misc.py:100", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "TextBoxConcatenate", "g": "Text and seeds", "d": "A multiline text box that adds an incoming string after or before the typed text, with an optional separator.", "u": "When typed text needs to be combined with text from another node.", "src": "nodes_misc.py:341", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "TextConcatenate", "g": "Text and seeds", "d": "Joins two incoming strings with an optional separator between them.", "u": "When two text wires need to become one.", "src": "nodes_misc.py:316", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "TextLoadFile", "g": "Text and seeds", "d": "Lists the .txt files in ComfyUI's input folder and outputs the chosen file's contents as a string. If the file is missing, it prints an error and returns an empty string.", "u": "When a prompt lives in a text file.", "src": "nodes_misc.py:126", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "TextShuffle", "g": "Text and seeds", "d": "Splits text on a separator, shuffles the pieces using a seed, and joins them back with the same separator.", "u": "When you want a repeatable random reordering of words or phrases.", "src": "nodes_misc.py:156", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "TextShuffleAndTruncate", "g": "Text and seeds", "d": "Shuffles the text by seed, cuts it to a word limit, then outputs versions trimmed to a token limit for CLIP-L, CLIP-G and T5. The clip input is marked optional, but the code reads clip.tokenizer without checking for it being empty.", "u": "When a shuffled prompt must also fit text encoder token limits.", "src": "nodes_misc.py:226", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "TextTruncateTokens", "g": "Text and seeds", "d": "Cuts text to a word limit and outputs versions trimmed to separate token limits for CLIP-L, CLIP-G and T5, dropping one word at a time until the tokenized length fits. CLIP-L and CLIP-G start from the full text, T5 from the word-limited text, and the clip input is read before its empty check.", "u": "When a prompt must fit each text encoder's token limit.", "src": "nodes_misc.py:271", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "TorchCompileModelAura", "g": "Compile for speed", "d": "Runs torch.compile on every double and single layer of an AuraFlow model and also sets PyTorch's dynamo cache size limit. It raises an error if the model has no such layers.", "u": "Use it to compile an AuraFlow model.", "src": "models.py:1461", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "TorchCompileModelFluxAdv", "g": "Compile for speed", "d": "Runs torch.compile on chosen Flux double and single blocks, picked with lists such as 0-18, and attaches them as patches on a copy of the model. It compiles only once per node instance, and the code says it was adapted from kijai's ComfyUI-KJNodes.", "u": "Use it to compile only some Flux blocks rather than all of them.", "src": "models.py:1383", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "TorchCompileModels", "g": "Compile for speed", "d": "Looks for the block lists used by Flux, AuraFlow, HiDream, SD3.5 and WAN style models and compiles every block it finds. Any triton_max_block_x above 0 sets the TRITON_MAX_BLOCK_X environment variable to 4096, whatever number was entered.", "u": "Use it as the single compile node when the model is one of the listed types.", "src": "models.py:98", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "TorchCompileModelSD35", "g": "Compile for speed", "d": "Runs torch.compile on every joint block of an SD3.5 model and also sets PyTorch's dynamo cache size limit.", "u": "Use it to compile an SD3.5 model.", "src": "models.py:1513", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "UltraSharkSampler", "g": "Legacy samplers and options", "d": "Deprecated. Samples Stable Cascade models, setting up the UltraCascade guide for the up stage or the prior and empty negative for Stage B. It declares three outputs but returns only two.", "u": "Its description says it is for Stable Cascade and UltraCascade.", "src": "legacy/samplers.py:681", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "UltraSharkSampler Tiled", "g": "Legacy samplers and options", "d": "Deprecated. Samples in tiles using padded, random, random strict or simple layouts, slicing conditioning, ControlNets and optional CLIP vision input for each tile, with batched tiles for Stage B. A code comment says the tiling code is adapted from BlenderNeko's ComfyUI_TiledKSampler.", "u": "Its description says it is for UltraCascade.", "src": "legacy/samplers_tiled.py:488", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "UNetSave", "g": "Swap and save weights", "d": "Saves a model to a .safetensors file under ComfyUI's output folder with no text encoder or VAE included, loading it with its patches applied first. It adds model-type metadata for some architectures and stores the workflow unless metadata is disabled.", "u": "Use it to save a patched or merged diffusion model on its own.", "src": "models.py:1255", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "VAEEncodeAdvanced", "g": "VAE and images", "d": "Resizes and encodes up to two images with a fixed seed of 42, picks one channel from a mask image and resizes it, and outputs the latents, mask, width, height and an empty latent. The size can come from the inputs or be copied from an image, mask or latent, and a connected latent is passed through in place of the empty one.", "u": "When one node should prepare matching image latents, a mask and an empty latent at the same size.", "src": "helper_sigma_preview_image_preproc.py:191", "s": "untested", "e": "", "t": "", "j": "", "w": ""}, {"n": "VAEStyleTransferLatent", "g": "VAE and images", "d": "Passes a latent and a style latent through a copy of one convolution layer from the VAE, matches their statistics with AdaIN or WCT, and uses a pseudo-inverse of that layer to get back to a latent. It prefers raw_x from state_info when present, and takes different paths for Stable Cascade stage A, standard decoder VAEs and Stage C.", "u": "When you want to apply a style latent's statistics without running a sampler.", "src": "helper_sigma_preview_image_preproc.py:322", "s": "untested", "e": "", "t": "", "j": "", "w": ""}];
